-- ===== 20260110000000_ship_options.sql =====
-- Callebrownies migration 10: three ways to get an order (Sameday shipment, Pickup, Scheduled delivery), each with an on/off switch and a lead time.
-- Safe to run more than once. Run after migration 1 (works with or without 2 to 9).

create or replace function public.place_order(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s jsonb := public.cfg(); t bigint := public.now_ms();
  v_size int; v_mode text; v_day text; v_time text; v_note text; v_notify text; v_coupon text; v_expect numeric;
  v_name text; v_email text; v_phone text; v_addr text; items jsonb := '{}'::jsonb; addon_ids jsonb := '[]'::jsonb;
  edit_id text := nullif(p ->> 'editId', ''); edit_tok text := p ->> 'editToken'; eo public.orders;
  k text; n int; total_items int := 0; prod record; surcharge numeric := 0; addons_total numeric := 0; a record; aid text;
  base numeric; sale jsonb; sd numeric := 0; cp jsonb; cdisc numeric := 0; fee numeric := 0; total numeric;
  win int := coalesce((s ->> 'payWindowH')::int, 24); today date; dte date; v_code text; oid text; tok text;
  v_speed text; lead numeric; sh int; earliest date; od jsonb; ms jsonb := '[]'::jsonb; msg text; ch text; sale_txt text := ''; tries int := 0; open_n int; own_stock int;
begin
  perform public.sweep_orders();
  if length(p::text) > 20000 then perform public.bad('That order is too large.'); end if;

  -- basic fields
  v_size := coalesce((p ->> 'size')::int, 0);
  v_mode := p ->> 'mode';        if v_mode not in ('pickup','delivery') then perform public.bad('Choose pickup or delivery.'); end if;
  v_speed := case when v_mode = 'pickup' then 'pickup' when p ->> 'speed' = 'sameday' then 'sameday' else 'scheduled' end;
  v_day := p ->> 'day';          v_time := p ->> 'time';
  v_note := left(coalesce(p ->> 'note', ''), 300);
  v_notify := coalesce(p ->> 'notify', 'both'); if v_notify not in ('whatsapp','email','both','none') then v_notify := 'both'; end if;
  v_coupon := upper(regexp_replace(coalesce(p ->> 'coupon', ''), '[^A-Za-z0-9_-]', '', 'g'));
  v_expect := nullif(p ->> 'expectTotal', '')::numeric;
  v_name  := btrim(coalesce(p #>> '{customer,name}', ''));
  v_email := btrim(coalesce(p #>> '{customer,email}', ''));
  v_phone := regexp_replace(coalesce(p #>> '{customer,phone}', ''), '\D', '', 'g');
  v_addr  := btrim(coalesce(p #>> '{customer,address}', ''));
  if length(v_name) < 1 or length(v_name) > 80 then perform public.bad('Please enter your name.'); end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 120 then perform public.bad('Please enter a valid email address.'); end if;
  if v_phone !~ '^\d{8,15}$' then perform public.bad('WhatsApp number: use numbers only, 8 to 15 digits.'); end if;
  if v_mode = 'delivery' then
    if length(v_addr) < 5 or length(v_addr) > 300 then perform public.bad('Please enter your delivery address.'); end if;
  else v_addr := ''; end if;

  -- schedule: pickup, scheduled delivery and sameday shipment each have an on/off switch and their own lead time
  today := (now() at time zone public.shop_tz())::date;
  sh := extract(hour from (now() at time zone public.shop_tz()))::int;
  if (v_speed = 'pickup' and not coalesce((s ->> 'pickupOn')::boolean, true))
     or (v_speed = 'scheduled' and not coalesce((s ->> 'schedOn')::boolean, true))
     or (v_speed = 'sameday' and not coalesce((s ->> 'samedayOn')::boolean, false)) then
    perform public.bad('That option isn''t available right now. Please choose another way to get your order.'); end if;
  if v_speed = 'sameday' then
    if sh >= coalesce((s ->> 'samedayCutoff')::int, 15) then
      perform public.bad('Sameday shipment is closed for today. Please choose another option.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from today)::int) then
      perform public.bad('We''re closed today. Please choose another option.'); end if;
    dte := today; v_day := today::text; v_time := 'Same day';
  else
    if v_day !~ '^\d{4}-\d{2}-\d{2}$' then perform public.bad('Please pick a day.'); end if;
    begin dte := v_day::date; exception when others then perform public.bad('Please pick a day.'); end;
    lead := greatest(0, least(720, coalesce((s ->> case v_speed when 'pickup' then 'pickupLeadH' else 'schedLeadH' end)::numeric, 24)));
    earliest := ((now() at time zone public.shop_tz()) + make_interval(hours => ceil(lead)::int))::date;
    if sh >= coalesce((s ->> 'cutoffHour')::int, 20) then earliest := earliest + 1; end if;
    if dte < earliest or dte > earliest + 6 then perform public.bad('Please pick another day.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from dte)::int) then
      perform public.bad('We''re closed that day. Please pick another day.'); end if;
    if not exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'times', '[]'::jsonb)) w where w = v_time) then
      perform public.bad('Please pick a time.'); end if;
  end if;

  -- editing an existing unpaid order?
  if edit_id is not null then
    select * into eo from public.orders where id = edit_id for update;
    if not found or not exists (select 1 from public.order_tokens where order_id = edit_id and hash = public.tok_hash(edit_tok)) then
      perform public.bad('We couldn''t find that order.'); end if;
    if eo.status <> 'awaiting' then perform public.bad('This order can''t be edited any more.'); end if;
  else
    if not public.throttle_ok('order', 60, 60000) then perform public.bad('We''re very busy right now. Please try again in a minute.'); end if;
    select count(*) into open_n from public.orders where phone_norm = public.norm_phone(v_phone) and status = 'awaiting';
    if open_n >= 3 then perform public.bad('You already have 3 unpaid orders. Please pay or cancel one first.'); end if;
    if (select count(*) from public.orders where status = 'awaiting') >= coalesce((s ->> 'maxOpenOrders')::int, 150) then
      perform public.bad('We''re very busy right now. Please try again a little later.'); end if;
  end if;

  -- items
  if jsonb_typeof(p -> 'items') <> 'object' then perform public.bad('Your box is empty.'); end if;
  for k, n in select key, (value)::int from jsonb_each_text(p -> 'items') loop
    if n < 1 or n > 100 then perform public.bad('Please check your box.'); end if;
    items := items || jsonb_build_object(k, n); total_items := total_items + n;
  end loop;
  base := public.base_price(v_size);
  if base <= 0 then perform public.bad('That box size isn''t available.'); end if;
  if total_items <> v_size then perform public.bad('Please fill every spot in your box.'); end if;

  -- give back this order's own hold first, so stock checks see it
  if edit_id is not null and coalesce((eo.data ->> 'holds')::boolean, false) then
    for k, n in select key, value::int from jsonb_each_text(eo.data -> 'items') loop
      update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) + n)), updated_at = t
      where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
    end loop;
  end if;

  for k, n in select key, value::int from jsonb_each_text(items) order by key loop
    select * into prod from public.coll where coll = 'products' and id = k for update;
    if not found or prod.data ->> 'status' <> 'available' then
      perform public.bad('Sorry, ' || coalesce(prod.data ->> 'name', 'that flavor') || ' just sold out. Please change your box.'); end if;
    if coalesce((prod.data ->> 'track')::boolean, false) then
      own_stock := coalesce((prod.data ->> 'stock')::int, 0);
      if n > own_stock then
        perform public.bad(case when own_stock > 0 then 'Sorry, only ' || own_stock || ' ' || (prod.data ->> 'name') || ' left. Please change your box.'
                                else 'Sorry, ' || (prod.data ->> 'name') || ' just sold out. Please change your box.' end);
      end if;
    end if;
    surcharge := surcharge + coalesce((prod.data ->> 'surcharge')::numeric, 0) * n;
  end loop;
  surcharge := round(surcharge, 2);

  -- extras
  if jsonb_typeof(p -> 'addons') = 'array' then
    for aid in select distinct value from jsonb_array_elements_text(p -> 'addons') loop
      select * into a from public.coll where coll = 'addons' and id = aid;
      if found and coalesce((a.data ->> 'active')::boolean, true) then
        addons_total := addons_total + (a.data ->> 'price')::numeric; addon_ids := addon_ids || to_jsonb(aid);
      end if;
    end loop;
  end if;
  addons_total := round(addons_total, 2);

  -- sale + coupon + delivery fee
  sale := public.best_sale(v_size, base, t);
  if sale is not null then sd := (sale ->> 'discount')::numeric; sale_txt := sale ->> 'text'; end if;
  if v_coupon <> '' then
    cp := public.cp_eval(v_coupon, v_size, v_phone, edit_id, base, sd);
    if not (cp ->> 'ok')::boolean then perform public.bad((cp ->> 'err') || ' Remove the coupon to continue.'); end if;
    cdisc := (cp ->> 'discount')::numeric;
  end if;
  if v_mode = 'delivery' and not coalesce((cp ->> 'freeDel')::boolean, false) then
    fee := case when v_speed = 'sameday' then coalesce((s ->> 'samedayFee')::numeric, (s ->> 'deliveryFee')::numeric, 0) else coalesce((s ->> 'deliveryFee')::numeric, 0) end; end if;
  total := round(base - sd - cdisc + surcharge + addons_total + fee, 2);
  if v_expect is not null and abs(v_expect - total) > 0.015 then
    perform public.bad('Prices changed while you were checking out. The new total is ' || public.money_txt(total) || '. Please review and place your order again.'); end if;

  -- take stock
  for k, n in select key, value::int from jsonb_each_text(items) loop
    update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) - n)), updated_at = t
    where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
  end loop;

  if edit_id is not null then
    od := eo.data || jsonb_build_object('notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time,
      'note', v_note, 'addons', addon_ids, 'sale', sale_txt, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc,
      'surcharge', surcharge, 'addonsTotal', addons_total, 'fee', fee, 'total', total, 'holds', true, 'tracked', true, 'editedAt', t,
      'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr));
    update public.orders set data = od where id = edit_id;
    return jsonb_build_object('order', od);
  end if;

  loop
    v_code := 'DD-' || (select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', 1 + floor(random() * 32)::int, 1), '') from generate_series(1, 6));
    exit when not exists (select 1 from public.orders where orders.code = v_code);
    tries := tries + 1; if tries > 20 then perform public.bad('Please try again.'); end if;
  end loop;
  oid := substr(replace(gen_random_uuid()::text, '-', ''), 1, 16);
  tok := public.new_token();

  msg := 'Hi ' || coalesce(nullif(split_part(v_name, ' ', 1), ''), 'there') || ', your Callebrownies order ' || v_code || ' (' || public.money_txt(total)
         || ') is waiting for payment. Please pay and send your proof in My orders before it is cancelled automatically.';
  for ch in select unnest(case v_notify when 'both' then array['whatsapp','email'] when 'none' then array[]::text[] else array[v_notify] end) loop
    ms := ms || jsonb_build_array(jsonb_build_object('at', t, 'channel', ch, 'status', 'awaiting', 'text', msg, 'by', 'system'));
  end loop;

  od := jsonb_build_object('id', oid, 'code', v_code, 'tracked', true, 'holds', true, 'createdAt', t, 'expiresAt', t + win * 3600000::bigint,
    'status', 'awaiting', 'notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time, 'note', v_note,
    'addons', addon_ids, 'sale', sale_txt, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc, 'surcharge', surcharge,
    'addonsTotal', addons_total, 'fee', fee, 'total', total,
    'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr), 'msgs', ms);
  insert into public.orders (id, code, status, phone_norm, created_at, updated_at, expires_at, data)
    values (oid, v_code, 'awaiting', public.norm_phone(v_phone), t, t, t + win * 3600000::bigint, od);
  insert into public.order_tokens values (oid, public.tok_hash(tok), t);
  return jsonb_build_object('order', od, 'token', tok);
end $$;

-- the sameday fee is a price: it needs the owner password to change (only when the team tab/guards from migration 6 are installed)
do $m$ begin
  if to_regprocedure('public.docs_guard()') is not null then
    execute $g$
create or replace function public.docs_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare k text := coalesce(new.key, old.key); perm text; o jsonb; n jsonb; ch text; lbl text;
begin
  if coalesce(current_setting('dd.op', true), '') <> 'team' then return coalesce(new, old); end if;
  if tg_op = 'INSERT' and exists (select 1 from public.docs x where x.key = new.key) then return new; end if;
  if tg_op <> 'INSERT' then o := old.data; end if;
  if tg_op <> 'DELETE' then n := new.data; end if;
  perm := case when k in ('settings','payMethods','thanks','proofpop') then 'settings' when k in ('page','marquee','announcer') then 'design'
               when k = 'badges' then 'badges' when k = 'label' then 'labels' when k = 'alerts' then null else 'settings' end;
  if perm is not null and not public.has_perm(perm) then raise exception 'You don''t have access to change this. Ask the owner.' using errcode = '42501'; end if;
  if k = 'settings' and tg_op = 'UPDATE' and not public.sudo_ok() and
     ((o -> 'deliveryFee') is distinct from (n -> 'deliveryFee') or (o -> 'customPer') is distinct from (n -> 'customPer')
      or (o ? 'samedayFee' and (o -> 'samedayFee') is distinct from (n -> 'samedayFee'))) then
    raise exception 'Owner password needed to change a price.' using errcode = 'P0001'; end if;
  if k = 'alerts' then return coalesce(new, old); end if;
  lbl := case k when 'settings' then 'shop settings' when 'payMethods' then 'payment methods' when 'thanks' then 'order placed page'
                when 'proofpop' then 'payment popup' when 'page' then 'landing page / top banner' when 'marquee' then 'marquee banner'
                when 'announcer' then 'announcer' when 'badges' then 'badges' when 'label' then 'shipping label' else k end;
  if k = 'settings' then ch := public.chg_list(o, n, array['deliveryFee','samedayFee','customPer','currency','payWindowH','cutoffHour','lowStockAt','menuSort','samedayOn','samedayLeadH','samedayCutoff','pickupOn','pickupLeadH','schedOn','schedLeadH']);
  else ch := ''; end if;
  if (o is distinct from n) then perform public.log_act('Edited ' || lbl, ch); end if;
  return coalesce(new, old);
end $$;
    $g$;
  end if;
end $m$;


-- ===== 20260111000000_free_delivery_promo.sql =====
-- Callebrownies migration 11: scheduled "Free delivery" promos in the Flash sales menu (they work like flash sales: start, end, box size).
-- Safe to run more than once. Run after migration 10.

create or replace function public.free_del_live(p_n int, p_at bigint) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.coll s
                 where s.coll = 'sales' and s.data ->> 'type' = 'freedelivery'
                   and (s.data ->> 'start')::bigint <= p_at and p_at < (s.data ->> 'end')::bigint
                   and (s.data ->> 'appliesTo' = 'all' or (s.data ->> 'appliesTo') = p_n::text))
$$;
revoke all on function public.free_del_live(int, bigint) from public, anon, authenticated;

create or replace function public.best_sale(p_n int, p_price numeric, p_at bigint) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare r jsonb;
begin
  select jsonb_build_object('id', s.data ->> 'id', 'name', s.data ->> 'name', 'discount', d,
           'text', (s.data ->> 'name') || ' (' ||
                   case when s.data ->> 'type' = 'percent' then (s.data ->> 'value') || '% off'
                        else public.money_txt((s.data ->> 'value')::numeric) || ' off' end || ')')
    into r
  from (select s2.data,
               case when s2.data ->> 'type' = 'percent'
                    then round(p_price * (s2.data ->> 'value')::numeric / 100, 2)
                    else round(least((s2.data ->> 'value')::numeric, p_price), 2) end as d
        from public.coll s2
        where s2.coll = 'sales' and coalesce(s2.data ->> 'type', '') <> 'freedelivery'
          and (s2.data ->> 'start')::bigint <= p_at and p_at < (s2.data ->> 'end')::bigint
          and (s2.data ->> 'appliesTo' = 'all' or (s2.data ->> 'appliesTo') = p_n::text)) s
  order by d desc limit 1;
  return r;
end $$;

create or replace function public.place_order(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s jsonb := public.cfg(); t bigint := public.now_ms();
  v_size int; v_mode text; v_day text; v_time text; v_note text; v_notify text; v_coupon text; v_expect numeric;
  v_name text; v_email text; v_phone text; v_addr text; items jsonb := '{}'::jsonb; addon_ids jsonb := '[]'::jsonb;
  edit_id text := nullif(p ->> 'editId', ''); edit_tok text := p ->> 'editToken'; eo public.orders;
  k text; n int; total_items int := 0; prod record; surcharge numeric := 0; addons_total numeric := 0; a record; aid text;
  base numeric; sale jsonb; sd numeric := 0; cp jsonb; cdisc numeric := 0; fee numeric := 0; total numeric;
  win int := coalesce((s ->> 'payWindowH')::int, 24); today date; dte date; v_code text; oid text; tok text;
  v_speed text; lead numeric; sh int; earliest date; od jsonb; ms jsonb := '[]'::jsonb; msg text; ch text; sale_txt text := ''; tries int := 0; open_n int; own_stock int;
begin
  perform public.sweep_orders();
  if length(p::text) > 20000 then perform public.bad('That order is too large.'); end if;

  -- basic fields
  v_size := coalesce((p ->> 'size')::int, 0);
  v_mode := p ->> 'mode';        if v_mode not in ('pickup','delivery') then perform public.bad('Choose pickup or delivery.'); end if;
  v_speed := case when v_mode = 'pickup' then 'pickup' when p ->> 'speed' = 'sameday' then 'sameday' else 'scheduled' end;
  v_day := p ->> 'day';          v_time := p ->> 'time';
  v_note := left(coalesce(p ->> 'note', ''), 300);
  v_notify := coalesce(p ->> 'notify', 'both'); if v_notify not in ('whatsapp','email','both','none') then v_notify := 'both'; end if;
  v_coupon := upper(regexp_replace(coalesce(p ->> 'coupon', ''), '[^A-Za-z0-9_-]', '', 'g'));
  v_expect := nullif(p ->> 'expectTotal', '')::numeric;
  v_name  := btrim(coalesce(p #>> '{customer,name}', ''));
  v_email := btrim(coalesce(p #>> '{customer,email}', ''));
  v_phone := regexp_replace(coalesce(p #>> '{customer,phone}', ''), '\D', '', 'g');
  v_addr  := btrim(coalesce(p #>> '{customer,address}', ''));
  if length(v_name) < 1 or length(v_name) > 80 then perform public.bad('Please enter your name.'); end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 120 then perform public.bad('Please enter a valid email address.'); end if;
  if v_phone !~ '^\d{8,15}$' then perform public.bad('WhatsApp number: use numbers only, 8 to 15 digits.'); end if;
  if v_mode = 'delivery' then
    if length(v_addr) < 5 or length(v_addr) > 300 then perform public.bad('Please enter your delivery address.'); end if;
  else v_addr := ''; end if;

  -- schedule: pickup, scheduled delivery and sameday shipment each have an on/off switch and their own lead time
  today := (now() at time zone public.shop_tz())::date;
  sh := extract(hour from (now() at time zone public.shop_tz()))::int;
  if (v_speed = 'pickup' and not coalesce((s ->> 'pickupOn')::boolean, true))
     or (v_speed = 'scheduled' and not coalesce((s ->> 'schedOn')::boolean, true))
     or (v_speed = 'sameday' and not coalesce((s ->> 'samedayOn')::boolean, false)) then
    perform public.bad('That option isn''t available right now. Please choose another way to get your order.'); end if;
  if v_speed = 'sameday' then
    if sh >= coalesce((s ->> 'samedayCutoff')::int, 15) then
      perform public.bad('Sameday shipment is closed for today. Please choose another option.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from today)::int) then
      perform public.bad('We''re closed today. Please choose another option.'); end if;
    dte := today; v_day := today::text; v_time := 'Same day';
  else
    if v_day !~ '^\d{4}-\d{2}-\d{2}$' then perform public.bad('Please pick a day.'); end if;
    begin dte := v_day::date; exception when others then perform public.bad('Please pick a day.'); end;
    lead := greatest(0, least(720, coalesce((s ->> case v_speed when 'pickup' then 'pickupLeadH' else 'schedLeadH' end)::numeric, 24)));
    earliest := ((now() at time zone public.shop_tz()) + make_interval(hours => ceil(lead)::int))::date;
    if sh >= coalesce((s ->> 'cutoffHour')::int, 20) then earliest := earliest + 1; end if;
    if dte < earliest or dte > earliest + 6 then perform public.bad('Please pick another day.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from dte)::int) then
      perform public.bad('We''re closed that day. Please pick another day.'); end if;
    if not exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'times', '[]'::jsonb)) w where w = v_time) then
      perform public.bad('Please pick a time.'); end if;
  end if;

  -- editing an existing unpaid order?
  if edit_id is not null then
    select * into eo from public.orders where id = edit_id for update;
    if not found or not exists (select 1 from public.order_tokens where order_id = edit_id and hash = public.tok_hash(edit_tok)) then
      perform public.bad('We couldn''t find that order.'); end if;
    if eo.status <> 'awaiting' then perform public.bad('This order can''t be edited any more.'); end if;
  else
    if not public.throttle_ok('order', 60, 60000) then perform public.bad('We''re very busy right now. Please try again in a minute.'); end if;
    select count(*) into open_n from public.orders where phone_norm = public.norm_phone(v_phone) and status = 'awaiting';
    if open_n >= 3 then perform public.bad('You already have 3 unpaid orders. Please pay or cancel one first.'); end if;
    if (select count(*) from public.orders where status = 'awaiting') >= coalesce((s ->> 'maxOpenOrders')::int, 150) then
      perform public.bad('We''re very busy right now. Please try again a little later.'); end if;
  end if;

  -- items
  if jsonb_typeof(p -> 'items') <> 'object' then perform public.bad('Your box is empty.'); end if;
  for k, n in select key, (value)::int from jsonb_each_text(p -> 'items') loop
    if n < 1 or n > 100 then perform public.bad('Please check your box.'); end if;
    items := items || jsonb_build_object(k, n); total_items := total_items + n;
  end loop;
  base := public.base_price(v_size);
  if base <= 0 then perform public.bad('That box size isn''t available.'); end if;
  if total_items <> v_size then perform public.bad('Please fill every spot in your box.'); end if;

  -- give back this order's own hold first, so stock checks see it
  if edit_id is not null and coalesce((eo.data ->> 'holds')::boolean, false) then
    for k, n in select key, value::int from jsonb_each_text(eo.data -> 'items') loop
      update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) + n)), updated_at = t
      where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
    end loop;
  end if;

  for k, n in select key, value::int from jsonb_each_text(items) order by key loop
    select * into prod from public.coll where coll = 'products' and id = k for update;
    if not found or prod.data ->> 'status' <> 'available' then
      perform public.bad('Sorry, ' || coalesce(prod.data ->> 'name', 'that flavor') || ' just sold out. Please change your box.'); end if;
    if coalesce((prod.data ->> 'track')::boolean, false) then
      own_stock := coalesce((prod.data ->> 'stock')::int, 0);
      if n > own_stock then
        perform public.bad(case when own_stock > 0 then 'Sorry, only ' || own_stock || ' ' || (prod.data ->> 'name') || ' left. Please change your box.'
                                else 'Sorry, ' || (prod.data ->> 'name') || ' just sold out. Please change your box.' end);
      end if;
    end if;
    surcharge := surcharge + coalesce((prod.data ->> 'surcharge')::numeric, 0) * n;
  end loop;
  surcharge := round(surcharge, 2);

  -- extras
  if jsonb_typeof(p -> 'addons') = 'array' then
    for aid in select distinct value from jsonb_array_elements_text(p -> 'addons') loop
      select * into a from public.coll where coll = 'addons' and id = aid;
      if found and coalesce((a.data ->> 'active')::boolean, true) then
        addons_total := addons_total + (a.data ->> 'price')::numeric; addon_ids := addon_ids || to_jsonb(aid);
      end if;
    end loop;
  end if;
  addons_total := round(addons_total, 2);

  -- sale + coupon + delivery fee
  sale := public.best_sale(v_size, base, t);
  if sale is not null then sd := (sale ->> 'discount')::numeric; sale_txt := sale ->> 'text'; end if;
  if v_coupon <> '' then
    cp := public.cp_eval(v_coupon, v_size, v_phone, edit_id, base, sd);
    if not (cp ->> 'ok')::boolean then perform public.bad((cp ->> 'err') || ' Remove the coupon to continue.'); end if;
    cdisc := (cp ->> 'discount')::numeric;
  end if;
  if v_mode = 'delivery' and not coalesce((cp ->> 'freeDel')::boolean, false) and not public.free_del_live(v_size, t) then
    fee := case when v_speed = 'sameday' then coalesce((s ->> 'samedayFee')::numeric, (s ->> 'deliveryFee')::numeric, 0) else coalesce((s ->> 'deliveryFee')::numeric, 0) end; end if;
  total := round(base - sd - cdisc + surcharge + addons_total + fee, 2);
  if v_expect is not null and abs(v_expect - total) > 0.015 then
    perform public.bad('Prices changed while you were checking out. The new total is ' || public.money_txt(total) || '. Please review and place your order again.'); end if;

  -- take stock
  for k, n in select key, value::int from jsonb_each_text(items) loop
    update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) - n)), updated_at = t
    where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
  end loop;

  if edit_id is not null then
    od := eo.data || jsonb_build_object('notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time,
      'note', v_note, 'addons', addon_ids, 'sale', sale_txt, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc,
      'surcharge', surcharge, 'addonsTotal', addons_total, 'fee', fee, 'total', total, 'holds', true, 'tracked', true, 'editedAt', t,
      'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr));
    update public.orders set data = od where id = edit_id;
    return jsonb_build_object('order', od);
  end if;

  loop
    v_code := 'DD-' || (select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', 1 + floor(random() * 32)::int, 1), '') from generate_series(1, 6));
    exit when not exists (select 1 from public.orders where orders.code = v_code);
    tries := tries + 1; if tries > 20 then perform public.bad('Please try again.'); end if;
  end loop;
  oid := substr(replace(gen_random_uuid()::text, '-', ''), 1, 16);
  tok := public.new_token();

  msg := 'Hi ' || coalesce(nullif(split_part(v_name, ' ', 1), ''), 'there') || ', your Callebrownies order ' || v_code || ' (' || public.money_txt(total)
         || ') is waiting for payment. Please pay and send your proof in My orders before it is cancelled automatically.';
  for ch in select unnest(case v_notify when 'both' then array['whatsapp','email'] when 'none' then array[]::text[] else array[v_notify] end) loop
    ms := ms || jsonb_build_array(jsonb_build_object('at', t, 'channel', ch, 'status', 'awaiting', 'text', msg, 'by', 'system'));
  end loop;

  od := jsonb_build_object('id', oid, 'code', v_code, 'tracked', true, 'holds', true, 'createdAt', t, 'expiresAt', t + win * 3600000::bigint,
    'status', 'awaiting', 'notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time, 'note', v_note,
    'addons', addon_ids, 'sale', sale_txt, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc, 'surcharge', surcharge,
    'addonsTotal', addons_total, 'fee', fee, 'total', total,
    'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr), 'msgs', ms);
  insert into public.orders (id, code, status, phone_norm, created_at, updated_at, expires_at, data)
    values (oid, v_code, 'awaiting', public.norm_phone(v_phone), t, t, t + win * 3600000::bigint, od);
  insert into public.order_tokens values (oid, public.tok_hash(tok), t);
  return jsonb_build_object('order', od, 'token', tok);
end $$;


-- ===== 20260112000000_pay_deadline.sql =====
-- Callebrownies migration 12: the time to pay now follows the order's due time.
--   deadline = the earliest of: the usual payment window, or (pickup/delivery time - lead time).
--   Sameday orders get a short window (default 60 min). Nobody gets less than a minimum (default 30 min).
--   Time slots that are too soon for the lead time are refused. Safe to run more than once. Run after migration 11.

create or replace function public.slot_start_min(p text) returns int
language plpgsql immutable as $$
declare m text[]; h1 int; m1 int; h2 int; m2 int; s1 text; s2 text; a int; b int;
begin
  m := regexp_match(lower(coalesce(p, '')), '(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\s*(?:to|-|–|until)\s*(\d{1,2})(?::(\d{2}))?\s*(am|pm)?');
  if m is null then
    m := regexp_match(lower(coalesce(p, '')), '(\d{1,2})(?::(\d{2}))?\s*(am|pm)');
    if m is null then return null; end if;
    h1 := m[1]::int; m1 := coalesce(m[2]::int, 0);
    if h1 < 1 or h1 > 12 or m1 > 59 then return null; end if;
    return (h1 % 12 + case when m[3] = 'pm' then 12 else 0 end) * 60 + m1;
  end if;
  h1 := m[1]::int; m1 := coalesce(m[2]::int, 0); s1 := m[3];
  h2 := m[4]::int; m2 := coalesce(m[5]::int, 0); s2 := m[6];
  if h1 > 24 or h2 > 24 or m1 > 59 or m2 > 59 then return null; end if;
  if s1 is null and s2 is null then
    if h1 >= 24 then return null; end if;
    return h1 * 60 + m1;                                   -- 24-hour clock, e.g. "10 to 11" or "14:00-15:00"
  end if;
  if h1 < 1 or h1 > 12 or h2 < 1 or h2 > 12 then return null; end if;
  if s1 is null then
    s1 := s2;
    a := (h1 % 12 + case when s1 = 'pm' then 12 else 0 end) * 60 + m1;
    b := (h2 % 12 + case when s2 = 'pm' then 12 else 0 end) * 60 + m2;
    if a > b then s1 := case when s2 = 'pm' then 'am' else 'pm' end; end if;   -- "11 to 1pm" starts at 11am
  end if;
  return (h1 % 12 + case when s1 = 'pm' then 12 else 0 end) * 60 + m1;
end $$;

create or replace function public.sweep_orders() returns void
language plpgsql security definer set search_path = public as $$
declare r record; it record; t bigint := public.now_ms(); win int := coalesce((public.cfg() ->> 'payWindowH')::int, 24);
        msg text; ch text; ms jsonb;
begin
  for r in select id, data from public.orders
           where status = 'awaiting' and expires_at is not null and expires_at <= t order by id for update skip locked loop
    if coalesce((r.data ->> 'holds')::boolean, false) then
      for it in select key as pid, value::int as n from jsonb_each_text(r.data -> 'items') loop
        update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) + it.n)), updated_at = t
        where coll = 'products' and id = it.pid and coalesce((data ->> 'track')::boolean, false);
      end loop;
    end if;
    msg := 'Hi ' || coalesce(nullif(split_part(r.data #>> '{customer,name}', ' ', 1), ''), 'there') || ', your order ' || (r.data ->> 'code')
           || ' was cancelled. It was not paid in time, so it was cancelled automatically. Contact us if you have questions.';
    ms := '[]'::jsonb;
    for ch in select unnest(case coalesce(r.data ->> 'notify', 'both') when 'both' then array['whatsapp','email'] when 'none' then array[]::text[] else array[r.data ->> 'notify'] end) loop
      ms := ms || jsonb_build_array(jsonb_build_object('at', t, 'channel', ch, 'status', 'cancelled', 'text', msg, 'by', 'system'));
    end loop;
    update public.orders set data = (r.data || jsonb_build_object(
        'status', 'cancelled', 'holds', false,
        'cancelReason', 'Not paid within ' || win || ' hours, so it was cancelled automatically.',
        'msgs', coalesce(r.data -> 'msgs', '[]'::jsonb) || ms)) where id = r.id;
  end loop;
end $$;

create or replace function public.place_order(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s jsonb := public.cfg(); t bigint := public.now_ms();
  v_size int; v_mode text; v_day text; v_time text; v_note text; v_notify text; v_coupon text; v_expect numeric;
  v_name text; v_email text; v_phone text; v_addr text; items jsonb := '{}'::jsonb; addon_ids jsonb := '[]'::jsonb;
  edit_id text := nullif(p ->> 'editId', ''); edit_tok text := p ->> 'editToken'; eo public.orders;
  k text; n int; total_items int := 0; prod record; surcharge numeric := 0; addons_total numeric := 0; a record; aid text;
  base numeric; sale jsonb; sd numeric := 0; cp jsonb; cdisc numeric := 0; fee numeric := 0; total numeric;
  win int := coalesce((s ->> 'payWindowH')::int, 24); today date; dte date; v_code text; oid text; tok text;
  v_speed text; lead numeric; sh int; earliest date; exp_ms bigint; smin int; startms bigint; minpay int; od jsonb; ms jsonb := '[]'::jsonb; msg text; ch text; sale_txt text := ''; tries int := 0; open_n int; own_stock int;
begin
  perform public.sweep_orders();
  if length(p::text) > 20000 then perform public.bad('That order is too large.'); end if;

  -- basic fields
  v_size := coalesce((p ->> 'size')::int, 0);
  v_mode := p ->> 'mode';        if v_mode not in ('pickup','delivery') then perform public.bad('Choose pickup or delivery.'); end if;
  v_speed := case when v_mode = 'pickup' then 'pickup' when p ->> 'speed' = 'sameday' then 'sameday' else 'scheduled' end;
  v_day := p ->> 'day';          v_time := p ->> 'time';
  v_note := left(coalesce(p ->> 'note', ''), 300);
  v_notify := coalesce(p ->> 'notify', 'both'); if v_notify not in ('whatsapp','email','both','none') then v_notify := 'both'; end if;
  v_coupon := upper(regexp_replace(coalesce(p ->> 'coupon', ''), '[^A-Za-z0-9_-]', '', 'g'));
  v_expect := nullif(p ->> 'expectTotal', '')::numeric;
  v_name  := btrim(coalesce(p #>> '{customer,name}', ''));
  v_email := btrim(coalesce(p #>> '{customer,email}', ''));
  v_phone := regexp_replace(coalesce(p #>> '{customer,phone}', ''), '\D', '', 'g');
  v_addr  := btrim(coalesce(p #>> '{customer,address}', ''));
  if length(v_name) < 1 or length(v_name) > 80 then perform public.bad('Please enter your name.'); end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 120 then perform public.bad('Please enter a valid email address.'); end if;
  if v_phone !~ '^\d{8,15}$' then perform public.bad('WhatsApp number: use numbers only, 8 to 15 digits.'); end if;
  if v_mode = 'delivery' then
    if length(v_addr) < 5 or length(v_addr) > 300 then perform public.bad('Please enter your delivery address.'); end if;
  else v_addr := ''; end if;

  -- schedule: pickup, scheduled delivery and sameday shipment each have an on/off switch and their own lead time
  today := (now() at time zone public.shop_tz())::date;
  sh := extract(hour from (now() at time zone public.shop_tz()))::int;
  if (v_speed = 'pickup' and not coalesce((s ->> 'pickupOn')::boolean, true))
     or (v_speed = 'scheduled' and not coalesce((s ->> 'schedOn')::boolean, true))
     or (v_speed = 'sameday' and not coalesce((s ->> 'samedayOn')::boolean, false)) then
    perform public.bad('That option isn''t available right now. Please choose another way to get your order.'); end if;
  if v_speed = 'sameday' then
    if sh >= coalesce((s ->> 'samedayCutoff')::int, 15) then
      perform public.bad('Sameday shipment is closed for today. Please choose another option.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from today)::int) then
      perform public.bad('We''re closed today. Please choose another option.'); end if;
    dte := today; v_day := today::text; v_time := 'Same day';
  else
    if v_day !~ '^\d{4}-\d{2}-\d{2}$' then perform public.bad('Please pick a day.'); end if;
    begin dte := v_day::date; exception when others then perform public.bad('Please pick a day.'); end;
    lead := greatest(0, least(720, coalesce((s ->> case v_speed when 'pickup' then 'pickupLeadH' else 'schedLeadH' end)::numeric, 24)));
    earliest := ((now() at time zone public.shop_tz()) + make_interval(hours => ceil(lead)::int))::date;
    if sh >= coalesce((s ->> 'cutoffHour')::int, 20) then earliest := earliest + 1; end if;
    if dte < earliest or dte > earliest + 6 then perform public.bad('Please pick another day.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from dte)::int) then
      perform public.bad('We''re closed that day. Please pick another day.'); end if;
    if not exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'times', '[]'::jsonb)) w where w = v_time) then
      perform public.bad('Please pick a time.'); end if;
  end if;

  -- pay deadline: never later than (pickup/delivery time - lead time), and sameday orders get a short window
  minpay := greatest(1, coalesce((s ->> 'minPayMin')::int, 30));
  exp_ms := t + win * 3600000::bigint;
  if v_speed = 'sameday' then
    exp_ms := least(exp_ms, t + greatest(minpay, coalesce((s ->> 'samedayPayMin')::int, 60)) * 60000::bigint);
  else
    smin := public.slot_start_min(v_time);
    startms := (extract(epoch from ((dte + make_interval(mins => coalesce(smin, 540)))::timestamp at time zone public.shop_tz())) * 1000)::bigint;
    if smin is not null and startms < t + (lead * 3600000)::bigint + minpay * 60000::bigint then
      perform public.bad('That time is too soon for your order. Please pick a later time or day.'); end if;
    exp_ms := least(exp_ms, startms - (lead * 3600000)::bigint);
  end if;
  exp_ms := greatest(exp_ms, t + minpay * 60000::bigint);

  -- editing an existing unpaid order?
  if edit_id is not null then
    select * into eo from public.orders where id = edit_id for update;
    if not found or not exists (select 1 from public.order_tokens where order_id = edit_id and hash = public.tok_hash(edit_tok)) then
      perform public.bad('We couldn''t find that order.'); end if;
    if eo.status <> 'awaiting' then perform public.bad('This order can''t be edited any more.'); end if;
  else
    if not public.throttle_ok('order', 60, 60000) then perform public.bad('We''re very busy right now. Please try again in a minute.'); end if;
    select count(*) into open_n from public.orders where phone_norm = public.norm_phone(v_phone) and status = 'awaiting';
    if open_n >= 3 then perform public.bad('You already have 3 unpaid orders. Please pay or cancel one first.'); end if;
    if (select count(*) from public.orders where status = 'awaiting') >= coalesce((s ->> 'maxOpenOrders')::int, 150) then
      perform public.bad('We''re very busy right now. Please try again a little later.'); end if;
  end if;

  -- items
  if jsonb_typeof(p -> 'items') <> 'object' then perform public.bad('Your box is empty.'); end if;
  for k, n in select key, (value)::int from jsonb_each_text(p -> 'items') loop
    if n < 1 or n > 100 then perform public.bad('Please check your box.'); end if;
    items := items || jsonb_build_object(k, n); total_items := total_items + n;
  end loop;
  base := public.base_price(v_size);
  if base <= 0 then perform public.bad('That box size isn''t available.'); end if;
  if total_items <> v_size then perform public.bad('Please fill every spot in your box.'); end if;

  -- give back this order's own hold first, so stock checks see it
  if edit_id is not null and coalesce((eo.data ->> 'holds')::boolean, false) then
    for k, n in select key, value::int from jsonb_each_text(eo.data -> 'items') loop
      update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) + n)), updated_at = t
      where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
    end loop;
  end if;

  for k, n in select key, value::int from jsonb_each_text(items) order by key loop
    select * into prod from public.coll where coll = 'products' and id = k for update;
    if not found or prod.data ->> 'status' <> 'available' then
      perform public.bad('Sorry, ' || coalesce(prod.data ->> 'name', 'that flavor') || ' just sold out. Please change your box.'); end if;
    if coalesce((prod.data ->> 'track')::boolean, false) then
      own_stock := coalesce((prod.data ->> 'stock')::int, 0);
      if n > own_stock then
        perform public.bad(case when own_stock > 0 then 'Sorry, only ' || own_stock || ' ' || (prod.data ->> 'name') || ' left. Please change your box.'
                                else 'Sorry, ' || (prod.data ->> 'name') || ' just sold out. Please change your box.' end);
      end if;
    end if;
    surcharge := surcharge + coalesce((prod.data ->> 'surcharge')::numeric, 0) * n;
  end loop;
  surcharge := round(surcharge, 2);

  -- extras
  if jsonb_typeof(p -> 'addons') = 'array' then
    for aid in select distinct value from jsonb_array_elements_text(p -> 'addons') loop
      select * into a from public.coll where coll = 'addons' and id = aid;
      if found and coalesce((a.data ->> 'active')::boolean, true) then
        addons_total := addons_total + (a.data ->> 'price')::numeric; addon_ids := addon_ids || to_jsonb(aid);
      end if;
    end loop;
  end if;
  addons_total := round(addons_total, 2);

  -- sale + coupon + delivery fee
  sale := public.best_sale(v_size, base, t);
  if sale is not null then sd := (sale ->> 'discount')::numeric; sale_txt := sale ->> 'text'; end if;
  if v_coupon <> '' then
    cp := public.cp_eval(v_coupon, v_size, v_phone, edit_id, base, sd);
    if not (cp ->> 'ok')::boolean then perform public.bad((cp ->> 'err') || ' Remove the coupon to continue.'); end if;
    cdisc := (cp ->> 'discount')::numeric;
  end if;
  if v_mode = 'delivery' and not coalesce((cp ->> 'freeDel')::boolean, false) and not public.free_del_live(v_size, t) then
    fee := case when v_speed = 'sameday' then coalesce((s ->> 'samedayFee')::numeric, (s ->> 'deliveryFee')::numeric, 0) else coalesce((s ->> 'deliveryFee')::numeric, 0) end; end if;
  total := round(base - sd - cdisc + surcharge + addons_total + fee, 2);
  if v_expect is not null and abs(v_expect - total) > 0.015 then
    perform public.bad('Prices changed while you were checking out. The new total is ' || public.money_txt(total) || '. Please review and place your order again.'); end if;

  -- take stock
  for k, n in select key, value::int from jsonb_each_text(items) loop
    update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) - n)), updated_at = t
    where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
  end loop;

  if edit_id is not null then
    od := eo.data || jsonb_build_object('notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time,
      'note', v_note, 'addons', addon_ids, 'sale', sale_txt, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc,
      'surcharge', surcharge, 'addonsTotal', addons_total, 'fee', fee, 'total', total, 'holds', true, 'tracked', true, 'editedAt', t,
      'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr));
    update public.orders set data = od where id = edit_id;
    return jsonb_build_object('order', od);
  end if;

  loop
    v_code := 'DD-' || (select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', 1 + floor(random() * 32)::int, 1), '') from generate_series(1, 6));
    exit when not exists (select 1 from public.orders where orders.code = v_code);
    tries := tries + 1; if tries > 20 then perform public.bad('Please try again.'); end if;
  end loop;
  oid := substr(replace(gen_random_uuid()::text, '-', ''), 1, 16);
  tok := public.new_token();

  msg := 'Hi ' || coalesce(nullif(split_part(v_name, ' ', 1), ''), 'there') || ', your Callebrownies order ' || v_code || ' (' || public.money_txt(total)
         || ') is waiting for payment. Please pay and send your proof in My orders before it is cancelled automatically.';
  for ch in select unnest(case v_notify when 'both' then array['whatsapp','email'] when 'none' then array[]::text[] else array[v_notify] end) loop
    ms := ms || jsonb_build_array(jsonb_build_object('at', t, 'channel', ch, 'status', 'awaiting', 'text', msg, 'by', 'system'));
  end loop;

  od := jsonb_build_object('id', oid, 'code', v_code, 'tracked', true, 'holds', true, 'createdAt', t, 'expiresAt', exp_ms,
    'status', 'awaiting', 'notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time, 'note', v_note,
    'addons', addon_ids, 'sale', sale_txt, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc, 'surcharge', surcharge,
    'addonsTotal', addons_total, 'fee', fee, 'total', total,
    'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr), 'msgs', ms);
  insert into public.orders (id, code, status, phone_norm, created_at, updated_at, expires_at, data)
    values (oid, v_code, 'awaiting', public.norm_phone(v_phone), t, t, exp_ms, od);
  insert into public.order_tokens values (oid, public.tok_hash(tok), t);
  return jsonb_build_object('order', od, 'token', tok);
end $$;


-- ===== 20260113000000_refund_visitors.sql =====
-- Callebrownies migration 13:
--  * Visitor numbers are only sent to owners. Staff accounts get an empty list (hidden on the screen too).
--  * Refunds: an owner can mark a paid order as refunded (full or part). The customer sees it in the bell and in their order history.
-- Safe to run more than once. Run after migration 12.

create or replace function public.admin_load() returns jsonb
language plpgsql security definer set search_path = public as $$
declare nowt bigint := public.now_ms();
begin
  perform public.assert_admin();
  perform public.sweep_orders();
  return jsonb_build_object(
    'now', nowt,
    'docs', coalesce((select jsonb_object_agg(key, data) from public.docs), '{}'::jsonb),
    'colls', coalesce((select jsonb_object_agg(c, a) from (
        select coll as c, jsonb_agg(jsonb_build_object('id', id, 'pos', pos, 'data', data) order by pos, id) as a from public.coll group by coll) q), '{}'::jsonb),
    'orders', coalesce((select jsonb_agg(data order by created_at desc) from public.orders
                        where created_at > nowt - 180 * 86400000::bigint or status in ('awaiting','review','new','baking','ready')), '[]'::jsonb),
    'visits', case when not public.is_owner() then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('t', t2, 'v', vid)) from
        (select visits.t as t2, vid from public.visits where visits.t > nowt - 40 * 86400000::bigint order by t desc limit 4000) v), '[]'::jsonb) end);
end $$;

create or replace function public.admin_poll(p_since bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare t bigint := public.now_ms();
begin
  perform public.assert_admin();
  perform public.sweep_orders();
  return jsonb_build_object(
    'now', t,
    'orders', coalesce((select jsonb_agg(data order by created_at desc) from public.orders where updated_at > coalesce(p_since, 0)), '[]'::jsonb),
    'products', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'stock', data -> 'stock', 'reviews', coalesce(data -> 'reviews', '[]'::jsonb)))
                          from public.coll where coll = 'products' and updated_at > coalesce(p_since, 0)), '[]'::jsonb),
    'visits', case when not public.is_owner() then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('t', v.t, 'v', v.vid)) from public.visits v where v.t > coalesce(p_since, 0)), '[]'::jsonb) end);
end $$;

create or replace function public.admin_refund_order(p_id text, p_amount numeric, p_note text, p_msgs jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders; me public.admins := public.team_me(); amt numeric; tot numeric; d jsonb; m jsonb; t bigint := public.now_ms(); ms jsonb;
begin
  perform public.assert_admin();
  if me.role is distinct from 'owner' then perform public.bad('Only an owner can refund an order.'); end if;
  select * into o from public.orders where id = p_id for update;
  if not found then perform public.bad('Order not found'); end if;
  if not (o.data ? 'paidAt') then perform public.bad('Only an order that was paid can be refunded.'); end if;
  if o.data ? 'refund' then perform public.bad('This order is already marked as refunded.'); end if;
  tot := coalesce((o.data ->> 'total')::numeric, 0);
  amt := round(coalesce(p_amount, tot), 2);
  if amt <= 0 or amt > tot then perform public.bad('The refund must be more than 0 and no more than the order total.'); end if;
  ms := coalesce(o.data -> 'msgs', '[]'::jsonb);
  if jsonb_typeof(p_msgs) = 'array' then
    for m in select * from jsonb_array_elements(p_msgs) loop
      if m ->> 'channel' in ('whatsapp', 'email') and btrim(coalesce(m ->> 'text', '')) <> '' then
        ms := ms || jsonb_build_array(jsonb_build_object('at', t, 'channel', m ->> 'channel', 'status', 'refunded', 'text', left(m ->> 'text', 800), 'by', 'staff'));
      end if;
    end loop;
  end if;
  d := o.data || jsonb_build_object('msgs', ms, 'refund', jsonb_build_object(
         'amount', amt, 'full', amt >= tot, 'at', t, 'note', left(btrim(coalesce(p_note, '')), 200),
         'by', coalesce(nullif(me.name, ''), me.username, me.email)));
  perform set_config('dd.op', 'order', true);
  update public.orders set data = d, updated_at = t where id = p_id;
  perform public.log_act('Order ' || coalesce(d ->> 'code', p_id), 'refunded ' || amt::text || case when amt >= tot then ' (full)' else ' (part)' end);
  return d;
end $$;
revoke all on function public.admin_refund_order(text, numeric, text, jsonb) from public, anon, authenticated;
grant execute on function public.admin_refund_order(text, numeric, text, jsonb) to authenticated;


-- ===== 20260114000000_sales_performance.sql =====
-- Callebrownies migration 14: numbers for the dashboard Sales and Performance tabs.
--  * Orders remember when and by whom they were cancelled (cancelledAt, cancelBy = system | customer | owner | staff).
--  * Orders remember whether the customer used Random fill / Shuffle (shuffled).
-- Safe to run more than once. Run after migration 13.

create or replace function public.orders_sync() returns trigger
language plpgsql as $$
declare why text := coalesce(new.data ->> 'cancelReason', ''); who text;
begin
  new.status     := coalesce(new.data ->> 'status', new.status);
  new.expires_at := nullif(new.data ->> 'expiresAt', '')::bigint;
  new.phone_norm := public.norm_phone(new.data #>> '{customer,phone}');
  new.updated_at := public.now_ms();
  if new.status = 'cancelled' then
    if not (new.data ? 'cancelledAt') then
      who := case when why like 'Not paid%' then 'system' when why like 'You cancelled%' then 'customer'
                  else coalesce((select a.role from public.team_me() a), 'customer') end;
      new.data := new.data || jsonb_build_object('cancelledAt', new.updated_at, 'cancelBy', who);
    end if;
  elsif new.data ? 'cancelledAt' then
    new.data := new.data - 'cancelledAt' - 'cancelBy';
  end if;
  return new;
end $$;

-- orders cancelled before this update: work out who cancelled them from the reason and the messages
update public.orders o set data = o.data || jsonb_build_object(
    'cancelledAt', coalesce((select max((m ->> 'at')::bigint) from jsonb_array_elements(coalesce(o.data -> 'msgs', '[]'::jsonb)) m where m ->> 'status' = 'cancelled'), o.updated_at, o.created_at),
    'cancelBy', case when coalesce(o.data ->> 'cancelReason', '') like 'Not paid%' then 'system'
                     when coalesce(o.data ->> 'cancelReason', '') like 'You cancelled%' then 'customer' else 'owner' end)
 where o.status = 'cancelled' and not (o.data ? 'cancelledAt');

create or replace function public.place_order(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s jsonb := public.cfg(); t bigint := public.now_ms();
  v_size int; v_mode text; v_day text; v_time text; v_note text; v_notify text; v_coupon text; v_expect numeric;
  v_name text; v_email text; v_phone text; v_addr text; items jsonb := '{}'::jsonb; addon_ids jsonb := '[]'::jsonb;
  edit_id text := nullif(p ->> 'editId', ''); edit_tok text := p ->> 'editToken'; eo public.orders;
  k text; n int; total_items int := 0; prod record; surcharge numeric := 0; addons_total numeric := 0; a record; aid text;
  base numeric; sale jsonb; sd numeric := 0; cp jsonb; cdisc numeric := 0; fee numeric := 0; total numeric;
  win int := coalesce((s ->> 'payWindowH')::int, 24); today date; dte date; v_code text; oid text; tok text;
  v_speed text; lead numeric; sh int; earliest date; exp_ms bigint; smin int; startms bigint; minpay int; od jsonb; ms jsonb := '[]'::jsonb; msg text; ch text; sale_txt text := ''; tries int := 0; open_n int; own_stock int;
begin
  perform public.sweep_orders();
  if length(p::text) > 20000 then perform public.bad('That order is too large.'); end if;

  -- basic fields
  v_size := coalesce((p ->> 'size')::int, 0);
  v_mode := p ->> 'mode';        if v_mode not in ('pickup','delivery') then perform public.bad('Choose pickup or delivery.'); end if;
  v_speed := case when v_mode = 'pickup' then 'pickup' when p ->> 'speed' = 'sameday' then 'sameday' else 'scheduled' end;
  v_day := p ->> 'day';          v_time := p ->> 'time';
  v_note := left(coalesce(p ->> 'note', ''), 300);
  v_notify := coalesce(p ->> 'notify', 'both'); if v_notify not in ('whatsapp','email','both','none') then v_notify := 'both'; end if;
  v_coupon := upper(regexp_replace(coalesce(p ->> 'coupon', ''), '[^A-Za-z0-9_-]', '', 'g'));
  v_expect := nullif(p ->> 'expectTotal', '')::numeric;
  v_name  := btrim(coalesce(p #>> '{customer,name}', ''));
  v_email := btrim(coalesce(p #>> '{customer,email}', ''));
  v_phone := regexp_replace(coalesce(p #>> '{customer,phone}', ''), '\D', '', 'g');
  v_addr  := btrim(coalesce(p #>> '{customer,address}', ''));
  if length(v_name) < 1 or length(v_name) > 80 then perform public.bad('Please enter your name.'); end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 120 then perform public.bad('Please enter a valid email address.'); end if;
  if v_phone !~ '^\d{8,15}$' then perform public.bad('WhatsApp number: use numbers only, 8 to 15 digits.'); end if;
  if v_mode = 'delivery' then
    if length(v_addr) < 5 or length(v_addr) > 300 then perform public.bad('Please enter your delivery address.'); end if;
  else v_addr := ''; end if;

  -- schedule: pickup, scheduled delivery and sameday shipment each have an on/off switch and their own lead time
  today := (now() at time zone public.shop_tz())::date;
  sh := extract(hour from (now() at time zone public.shop_tz()))::int;
  if (v_speed = 'pickup' and not coalesce((s ->> 'pickupOn')::boolean, true))
     or (v_speed = 'scheduled' and not coalesce((s ->> 'schedOn')::boolean, true))
     or (v_speed = 'sameday' and not coalesce((s ->> 'samedayOn')::boolean, false)) then
    perform public.bad('That option isn''t available right now. Please choose another way to get your order.'); end if;
  if v_speed = 'sameday' then
    if sh >= coalesce((s ->> 'samedayCutoff')::int, 15) then
      perform public.bad('Sameday shipment is closed for today. Please choose another option.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from today)::int) then
      perform public.bad('We''re closed today. Please choose another option.'); end if;
    dte := today; v_day := today::text; v_time := 'Same day';
  else
    if v_day !~ '^\d{4}-\d{2}-\d{2}$' then perform public.bad('Please pick a day.'); end if;
    begin dte := v_day::date; exception when others then perform public.bad('Please pick a day.'); end;
    lead := greatest(0, least(720, coalesce((s ->> case v_speed when 'pickup' then 'pickupLeadH' else 'schedLeadH' end)::numeric, 24)));
    earliest := ((now() at time zone public.shop_tz()) + make_interval(hours => ceil(lead)::int))::date;
    if sh >= coalesce((s ->> 'cutoffHour')::int, 20) then earliest := earliest + 1; end if;
    if dte < earliest or dte > earliest + 6 then perform public.bad('Please pick another day.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from dte)::int) then
      perform public.bad('We''re closed that day. Please pick another day.'); end if;
    if not exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'times', '[]'::jsonb)) w where w = v_time) then
      perform public.bad('Please pick a time.'); end if;
  end if;

  -- pay deadline: never later than (pickup/delivery time - lead time), and sameday orders get a short window
  minpay := greatest(1, coalesce((s ->> 'minPayMin')::int, 30));
  exp_ms := t + win * 3600000::bigint;
  if v_speed = 'sameday' then
    exp_ms := least(exp_ms, t + greatest(minpay, coalesce((s ->> 'samedayPayMin')::int, 60)) * 60000::bigint);
  else
    smin := public.slot_start_min(v_time);
    startms := (extract(epoch from ((dte + make_interval(mins => coalesce(smin, 540)))::timestamp at time zone public.shop_tz())) * 1000)::bigint;
    if smin is not null and startms < t + (lead * 3600000)::bigint + minpay * 60000::bigint then
      perform public.bad('That time is too soon for your order. Please pick a later time or day.'); end if;
    exp_ms := least(exp_ms, startms - (lead * 3600000)::bigint);
  end if;
  exp_ms := greatest(exp_ms, t + minpay * 60000::bigint);

  -- editing an existing unpaid order?
  if edit_id is not null then
    select * into eo from public.orders where id = edit_id for update;
    if not found or not exists (select 1 from public.order_tokens where order_id = edit_id and hash = public.tok_hash(edit_tok)) then
      perform public.bad('We couldn''t find that order.'); end if;
    if eo.status <> 'awaiting' then perform public.bad('This order can''t be edited any more.'); end if;
  else
    if not public.throttle_ok('order', 60, 60000) then perform public.bad('We''re very busy right now. Please try again in a minute.'); end if;
    select count(*) into open_n from public.orders where phone_norm = public.norm_phone(v_phone) and status = 'awaiting';
    if open_n >= 3 then perform public.bad('You already have 3 unpaid orders. Please pay or cancel one first.'); end if;
    if (select count(*) from public.orders where status = 'awaiting') >= coalesce((s ->> 'maxOpenOrders')::int, 150) then
      perform public.bad('We''re very busy right now. Please try again a little later.'); end if;
  end if;

  -- items
  if jsonb_typeof(p -> 'items') <> 'object' then perform public.bad('Your box is empty.'); end if;
  for k, n in select key, (value)::int from jsonb_each_text(p -> 'items') loop
    if n < 1 or n > 100 then perform public.bad('Please check your box.'); end if;
    items := items || jsonb_build_object(k, n); total_items := total_items + n;
  end loop;
  base := public.base_price(v_size);
  if base <= 0 then perform public.bad('That box size isn''t available.'); end if;
  if total_items <> v_size then perform public.bad('Please fill every spot in your box.'); end if;

  -- give back this order's own hold first, so stock checks see it
  if edit_id is not null and coalesce((eo.data ->> 'holds')::boolean, false) then
    for k, n in select key, value::int from jsonb_each_text(eo.data -> 'items') loop
      update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) + n)), updated_at = t
      where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
    end loop;
  end if;

  for k, n in select key, value::int from jsonb_each_text(items) order by key loop
    select * into prod from public.coll where coll = 'products' and id = k for update;
    if not found or prod.data ->> 'status' <> 'available' then
      perform public.bad('Sorry, ' || coalesce(prod.data ->> 'name', 'that flavor') || ' just sold out. Please change your box.'); end if;
    if coalesce((prod.data ->> 'track')::boolean, false) then
      own_stock := coalesce((prod.data ->> 'stock')::int, 0);
      if n > own_stock then
        perform public.bad(case when own_stock > 0 then 'Sorry, only ' || own_stock || ' ' || (prod.data ->> 'name') || ' left. Please change your box.'
                                else 'Sorry, ' || (prod.data ->> 'name') || ' just sold out. Please change your box.' end);
      end if;
    end if;
    surcharge := surcharge + coalesce((prod.data ->> 'surcharge')::numeric, 0) * n;
  end loop;
  surcharge := round(surcharge, 2);

  -- extras
  if jsonb_typeof(p -> 'addons') = 'array' then
    for aid in select distinct value from jsonb_array_elements_text(p -> 'addons') loop
      select * into a from public.coll where coll = 'addons' and id = aid;
      if found and coalesce((a.data ->> 'active')::boolean, true) then
        addons_total := addons_total + (a.data ->> 'price')::numeric; addon_ids := addon_ids || to_jsonb(aid);
      end if;
    end loop;
  end if;
  addons_total := round(addons_total, 2);

  -- sale + coupon + delivery fee
  sale := public.best_sale(v_size, base, t);
  if sale is not null then sd := (sale ->> 'discount')::numeric; sale_txt := sale ->> 'text'; end if;
  if v_coupon <> '' then
    cp := public.cp_eval(v_coupon, v_size, v_phone, edit_id, base, sd);
    if not (cp ->> 'ok')::boolean then perform public.bad((cp ->> 'err') || ' Remove the coupon to continue.'); end if;
    cdisc := (cp ->> 'discount')::numeric;
  end if;
  if v_mode = 'delivery' and not coalesce((cp ->> 'freeDel')::boolean, false) and not public.free_del_live(v_size, t) then
    fee := case when v_speed = 'sameday' then coalesce((s ->> 'samedayFee')::numeric, (s ->> 'deliveryFee')::numeric, 0) else coalesce((s ->> 'deliveryFee')::numeric, 0) end; end if;
  total := round(base - sd - cdisc + surcharge + addons_total + fee, 2);
  if v_expect is not null and abs(v_expect - total) > 0.015 then
    perform public.bad('Prices changed while you were checking out. The new total is ' || public.money_txt(total) || '. Please review and place your order again.'); end if;

  -- take stock
  for k, n in select key, value::int from jsonb_each_text(items) loop
    update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) - n)), updated_at = t
    where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
  end loop;

  if edit_id is not null then
    od := eo.data || jsonb_build_object('notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time,
      'note', v_note, 'addons', addon_ids, 'sale', sale_txt, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc,
      'surcharge', surcharge, 'addonsTotal', addons_total, 'fee', fee, 'total', total, 'holds', true, 'tracked', true, 'editedAt', t,
      'shuffled', coalesce((p ->> 'shuffled')::boolean, false),
      'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr));
    update public.orders set data = od where id = edit_id;
    return jsonb_build_object('order', od);
  end if;

  loop
    v_code := 'DD-' || (select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', 1 + floor(random() * 32)::int, 1), '') from generate_series(1, 6));
    exit when not exists (select 1 from public.orders where orders.code = v_code);
    tries := tries + 1; if tries > 20 then perform public.bad('Please try again.'); end if;
  end loop;
  oid := substr(replace(gen_random_uuid()::text, '-', ''), 1, 16);
  tok := public.new_token();

  msg := 'Hi ' || coalesce(nullif(split_part(v_name, ' ', 1), ''), 'there') || ', your Callebrownies order ' || v_code || ' (' || public.money_txt(total)
         || ') is waiting for payment. Please pay and send your proof in My orders before it is cancelled automatically.';
  for ch in select unnest(case v_notify when 'both' then array['whatsapp','email'] when 'none' then array[]::text[] else array[v_notify] end) loop
    ms := ms || jsonb_build_array(jsonb_build_object('at', t, 'channel', ch, 'status', 'awaiting', 'text', msg, 'by', 'system'));
  end loop;

  od := jsonb_build_object('id', oid, 'code', v_code, 'tracked', true, 'holds', true, 'createdAt', t, 'expiresAt', exp_ms,
    'status', 'awaiting', 'notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time, 'note', v_note,
    'addons', addon_ids, 'sale', sale_txt, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc, 'surcharge', surcharge,
    'addonsTotal', addons_total, 'fee', fee, 'total', total, 'shuffled', coalesce((p ->> 'shuffled')::boolean, false),
    'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr), 'msgs', ms);
  insert into public.orders (id, code, status, phone_norm, created_at, updated_at, expires_at, data)
    values (oid, v_code, 'awaiting', public.norm_phone(v_phone), t, t, exp_ms, od);
  insert into public.order_tokens values (oid, public.tok_hash(tok), t);
  return jsonb_build_object('order', od, 'token', tok);
end $$;


-- ===== 20260115000000_owner_only_delete.sql =====
-- Callebrownies migration 15: only an owner account can delete flavors, extras, box sizes and categories
-- (staff who know the owner password still can't). Safe to run more than once. Run after migration 14.
do $do$
declare d text := pg_get_functiondef('public.coll_guard()'::regprocedure);
begin
  if position('Only an owner can delete this' in d) = 0 then
    d := replace(d,
      $a$if tg_op = 'DELETE' and c in ('products','categories','sizes','addons') and not public.sudo_ok() then$a$,
      $a$if tg_op = 'DELETE' and c in ('products','categories','sizes','addons') and not public.is_owner() then
    raise exception 'Only an owner can delete this.' using errcode = 'P0001'; end if;
  if tg_op = 'DELETE' and c in ('products','categories','sizes','addons') and not public.sudo_ok() then$a$);
    if position('Only an owner can delete this' in d) = 0 then raise exception 'coll_guard did not match, nothing changed'; end if;
    execute d;
  end if;
end $do$;


-- ===== 20260116000000_time_slots.sql =====
-- Callebrownies migration 16: time slots.
--  * Time slots are now one-hour boxes ("00 to 01" ... "22 to 23", 24-hour clock). The owner switches each on/off and can set a daily limit.
--  * A limit is only used up by orders whose payment is confirmed. A full slot can't be chosen (shown to customers as Full).
--  * The old free-text time list in Shop settings is converted to the new boxes (the same hours stay on; the owner can add more from the 00 to 01 ... 22 to 23 list).
-- Safe to run more than once. Run after migration 15.

create or replace function public.place_order(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  lim int; s jsonb := public.cfg(); t bigint := public.now_ms();
  v_size int; v_mode text; v_day text; v_time text; v_note text; v_notify text; v_coupon text; v_expect numeric;
  v_name text; v_email text; v_phone text; v_addr text; items jsonb := '{}'::jsonb; addon_ids jsonb := '[]'::jsonb;
  edit_id text := nullif(p ->> 'editId', ''); edit_tok text := p ->> 'editToken'; eo public.orders;
  k text; n int; total_items int := 0; prod record; surcharge numeric := 0; addons_total numeric := 0; a record; aid text;
  base numeric; sale jsonb; sd numeric := 0; cp jsonb; cdisc numeric := 0; fee numeric := 0; total numeric;
  win int := coalesce((s ->> 'payWindowH')::int, 24); today date; dte date; v_code text; oid text; tok text;
  v_speed text; lead numeric; sh int; earliest date; exp_ms bigint; smin int; startms bigint; minpay int; od jsonb; ms jsonb := '[]'::jsonb; msg text; ch text; sale_txt text := ''; tries int := 0; open_n int; own_stock int;
begin
  perform public.sweep_orders();
  if length(p::text) > 20000 then perform public.bad('That order is too large.'); end if;

  -- basic fields
  v_size := coalesce((p ->> 'size')::int, 0);
  v_mode := p ->> 'mode';        if v_mode not in ('pickup','delivery') then perform public.bad('Choose pickup or delivery.'); end if;
  v_speed := case when v_mode = 'pickup' then 'pickup' when p ->> 'speed' = 'sameday' then 'sameday' else 'scheduled' end;
  v_day := p ->> 'day';          v_time := p ->> 'time';
  v_note := left(coalesce(p ->> 'note', ''), 300);
  v_notify := coalesce(p ->> 'notify', 'both'); if v_notify not in ('whatsapp','email','both','none') then v_notify := 'both'; end if;
  v_coupon := upper(regexp_replace(coalesce(p ->> 'coupon', ''), '[^A-Za-z0-9_-]', '', 'g'));
  v_expect := nullif(p ->> 'expectTotal', '')::numeric;
  v_name  := btrim(coalesce(p #>> '{customer,name}', ''));
  v_email := btrim(coalesce(p #>> '{customer,email}', ''));
  v_phone := regexp_replace(coalesce(p #>> '{customer,phone}', ''), '\D', '', 'g');
  v_addr  := btrim(coalesce(p #>> '{customer,address}', ''));
  if length(v_name) < 1 or length(v_name) > 80 then perform public.bad('Please enter your name.'); end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 120 then perform public.bad('Please enter a valid email address.'); end if;
  if v_phone !~ '^\d{8,15}$' then perform public.bad('WhatsApp number: use numbers only, 8 to 15 digits.'); end if;
  if v_mode = 'delivery' then
    if length(v_addr) < 5 or length(v_addr) > 300 then perform public.bad('Please enter your delivery address.'); end if;
  else v_addr := ''; end if;

  -- schedule: pickup, scheduled delivery and sameday shipment each have an on/off switch and their own lead time
  today := (now() at time zone public.shop_tz())::date;
  sh := extract(hour from (now() at time zone public.shop_tz()))::int;
  if (v_speed = 'pickup' and not coalesce((s ->> 'pickupOn')::boolean, true))
     or (v_speed = 'scheduled' and not coalesce((s ->> 'schedOn')::boolean, true))
     or (v_speed = 'sameday' and not coalesce((s ->> 'samedayOn')::boolean, false)) then
    perform public.bad('That option isn''t available right now. Please choose another way to get your order.'); end if;
  if v_speed = 'sameday' then
    if sh >= coalesce((s ->> 'samedayCutoff')::int, 15) then
      perform public.bad('Sameday shipment is closed for today. Please choose another option.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from today)::int) then
      perform public.bad('We''re closed today. Please choose another option.'); end if;
    dte := today; v_day := today::text; v_time := 'Same day';
  else
    if v_day !~ '^\d{4}-\d{2}-\d{2}$' then perform public.bad('Please pick a day.'); end if;
    begin dte := v_day::date; exception when others then perform public.bad('Please pick a day.'); end;
    lead := greatest(0, least(720, coalesce((s ->> case v_speed when 'pickup' then 'pickupLeadH' else 'schedLeadH' end)::numeric, 24)));
    earliest := ((now() at time zone public.shop_tz()) + make_interval(hours => ceil(lead)::int))::date;
    if sh >= coalesce((s ->> 'cutoffHour')::int, 20) then earliest := earliest + 1; end if;
    if dte < earliest or dte > earliest + 6 then perform public.bad('Please pick another day.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from dte)::int) then
      perform public.bad('We''re closed that day. Please pick another day.'); end if;
    if not exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'times', '[]'::jsonb)) w where w = v_time) then
      perform public.bad('Please pick a time.'); end if;
    -- a time slot with a daily limit: only orders whose payment is confirmed use it up
    lim := coalesce((select (w ->> 'limit')::int from jsonb_array_elements(coalesce(s -> 'slots', '[]'::jsonb)) w where w ->> 't' = v_time limit 1), 0);
    if lim > 0 and (select count(*) from public.orders o2 where o2.data ->> 'day' = v_day and o2.data ->> 'time' = v_time
                      and o2.data ? 'paidAt' and o2.status <> 'cancelled' and o2.id is distinct from edit_id) >= lim then
      perform public.bad('Sorry, that time slot is full. Please pick another time.'); end if;
  end if;

  -- pay deadline: never later than (pickup/delivery time - lead time), and sameday orders get a short window
  minpay := greatest(1, coalesce((s ->> 'minPayMin')::int, 30));
  exp_ms := t + win * 3600000::bigint;
  if v_speed = 'sameday' then
    exp_ms := least(exp_ms, t + greatest(minpay, coalesce((s ->> 'samedayPayMin')::int, 60)) * 60000::bigint);
  else
    smin := public.slot_start_min(v_time);
    startms := (extract(epoch from ((dte + make_interval(mins => coalesce(smin, 540)))::timestamp at time zone public.shop_tz())) * 1000)::bigint;
    if smin is not null and startms < t + (lead * 3600000)::bigint + minpay * 60000::bigint then
      perform public.bad('That time is too soon for your order. Please pick a later time or day.'); end if;
    exp_ms := least(exp_ms, startms - (lead * 3600000)::bigint);
  end if;
  exp_ms := greatest(exp_ms, t + minpay * 60000::bigint);

  -- editing an existing unpaid order?
  if edit_id is not null then
    select * into eo from public.orders where id = edit_id for update;
    if not found or not exists (select 1 from public.order_tokens where order_id = edit_id and hash = public.tok_hash(edit_tok)) then
      perform public.bad('We couldn''t find that order.'); end if;
    if eo.status <> 'awaiting' then perform public.bad('This order can''t be edited any more.'); end if;
  else
    if not public.throttle_ok('order', 60, 60000) then perform public.bad('We''re very busy right now. Please try again in a minute.'); end if;
    select count(*) into open_n from public.orders where phone_norm = public.norm_phone(v_phone) and status = 'awaiting';
    if open_n >= 3 then perform public.bad('You already have 3 unpaid orders. Please pay or cancel one first.'); end if;
    if (select count(*) from public.orders where status = 'awaiting') >= coalesce((s ->> 'maxOpenOrders')::int, 150) then
      perform public.bad('We''re very busy right now. Please try again a little later.'); end if;
  end if;

  -- items
  if jsonb_typeof(p -> 'items') <> 'object' then perform public.bad('Your box is empty.'); end if;
  for k, n in select key, (value)::int from jsonb_each_text(p -> 'items') loop
    if n < 1 or n > 100 then perform public.bad('Please check your box.'); end if;
    items := items || jsonb_build_object(k, n); total_items := total_items + n;
  end loop;
  base := public.base_price(v_size);
  if base <= 0 then perform public.bad('That box size isn''t available.'); end if;
  if total_items <> v_size then perform public.bad('Please fill every spot in your box.'); end if;

  -- give back this order's own hold first, so stock checks see it
  if edit_id is not null and coalesce((eo.data ->> 'holds')::boolean, false) then
    for k, n in select key, value::int from jsonb_each_text(eo.data -> 'items') loop
      update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) + n)), updated_at = t
      where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
    end loop;
  end if;

  for k, n in select key, value::int from jsonb_each_text(items) order by key loop
    select * into prod from public.coll where coll = 'products' and id = k for update;
    if not found or prod.data ->> 'status' <> 'available' then
      perform public.bad('Sorry, ' || coalesce(prod.data ->> 'name', 'that flavor') || ' just sold out. Please change your box.'); end if;
    if coalesce((prod.data ->> 'track')::boolean, false) then
      own_stock := coalesce((prod.data ->> 'stock')::int, 0);
      if n > own_stock then
        perform public.bad(case when own_stock > 0 then 'Sorry, only ' || own_stock || ' ' || (prod.data ->> 'name') || ' left. Please change your box.'
                                else 'Sorry, ' || (prod.data ->> 'name') || ' just sold out. Please change your box.' end);
      end if;
    end if;
    surcharge := surcharge + coalesce((prod.data ->> 'surcharge')::numeric, 0) * n;
  end loop;
  surcharge := round(surcharge, 2);

  -- extras
  if jsonb_typeof(p -> 'addons') = 'array' then
    for aid in select distinct value from jsonb_array_elements_text(p -> 'addons') loop
      select * into a from public.coll where coll = 'addons' and id = aid;
      if found and coalesce((a.data ->> 'active')::boolean, true) then
        addons_total := addons_total + (a.data ->> 'price')::numeric; addon_ids := addon_ids || to_jsonb(aid);
      end if;
    end loop;
  end if;
  addons_total := round(addons_total, 2);

  -- sale + coupon + delivery fee
  sale := public.best_sale(v_size, base, t);
  if sale is not null then sd := (sale ->> 'discount')::numeric; sale_txt := sale ->> 'text'; end if;
  if v_coupon <> '' then
    cp := public.cp_eval(v_coupon, v_size, v_phone, edit_id, base, sd);
    if not (cp ->> 'ok')::boolean then perform public.bad((cp ->> 'err') || ' Remove the coupon to continue.'); end if;
    cdisc := (cp ->> 'discount')::numeric;
  end if;
  if v_mode = 'delivery' and not coalesce((cp ->> 'freeDel')::boolean, false) and not public.free_del_live(v_size, t) then
    fee := case when v_speed = 'sameday' then coalesce((s ->> 'samedayFee')::numeric, (s ->> 'deliveryFee')::numeric, 0) else coalesce((s ->> 'deliveryFee')::numeric, 0) end; end if;
  total := round(base - sd - cdisc + surcharge + addons_total + fee, 2);
  if v_expect is not null and abs(v_expect - total) > 0.015 then
    perform public.bad('Prices changed while you were checking out. The new total is ' || public.money_txt(total) || '. Please review and place your order again.'); end if;

  -- take stock
  for k, n in select key, value::int from jsonb_each_text(items) loop
    update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) - n)), updated_at = t
    where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
  end loop;

  if edit_id is not null then
    od := eo.data || jsonb_build_object('notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time,
      'note', v_note, 'addons', addon_ids, 'sale', sale_txt, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc,
      'surcharge', surcharge, 'addonsTotal', addons_total, 'fee', fee, 'total', total, 'holds', true, 'tracked', true, 'editedAt', t,
      'shuffled', coalesce((p ->> 'shuffled')::boolean, false),
      'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr));
    update public.orders set data = od where id = edit_id;
    return jsonb_build_object('order', od);
  end if;

  loop
    v_code := 'DD-' || (select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', 1 + floor(random() * 32)::int, 1), '') from generate_series(1, 6));
    exit when not exists (select 1 from public.orders where orders.code = v_code);
    tries := tries + 1; if tries > 20 then perform public.bad('Please try again.'); end if;
  end loop;
  oid := substr(replace(gen_random_uuid()::text, '-', ''), 1, 16);
  tok := public.new_token();

  msg := 'Hi ' || coalesce(nullif(split_part(v_name, ' ', 1), ''), 'there') || ', your Callebrownies order ' || v_code || ' (' || public.money_txt(total)
         || ') is waiting for payment. Please pay and send your proof in My orders before it is cancelled automatically.';
  for ch in select unnest(case v_notify when 'both' then array['whatsapp','email'] when 'none' then array[]::text[] else array[v_notify] end) loop
    ms := ms || jsonb_build_array(jsonb_build_object('at', t, 'channel', ch, 'status', 'awaiting', 'text', msg, 'by', 'system'));
  end loop;

  od := jsonb_build_object('id', oid, 'code', v_code, 'tracked', true, 'holds', true, 'createdAt', t, 'expiresAt', exp_ms,
    'status', 'awaiting', 'notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time, 'note', v_note,
    'addons', addon_ids, 'sale', sale_txt, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc, 'surcharge', surcharge,
    'addonsTotal', addons_total, 'fee', fee, 'total', total, 'shuffled', coalesce((p ->> 'shuffled')::boolean, false),
    'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr), 'msgs', ms);
  insert into public.orders (id, code, status, phone_norm, created_at, updated_at, expires_at, data)
    values (oid, v_code, 'awaiting', public.norm_phone(v_phone), t, t, exp_ms, od);
  insert into public.order_tokens values (oid, public.tok_hash(tok), t);
  return jsonb_build_object('order', od, 'token', tok);
end $$;

create or replace function public.shop_public() returns jsonb
language plpgsql security definer set search_path = public as $$
declare res jsonb;
begin
  perform public.sweep_orders();
  select jsonb_build_object(
    'now', public.now_ms(),
    'docs', coalesce((select jsonb_object_agg(key, data) from public.docs
                      where key in ('settings','page','marquee','announcer','thanks','proofpop','payMethods','badges')), '{}'::jsonb),
    'sizes', public.coll_arr('sizes'),
    'categories', public.coll_arr('categories'),
    'addons', public.coll_arr('addons'),
    'sales', public.coll_arr('sales'),
    'broadcasts', public.coll_arr('broadcasts'),
    'products', coalesce((select jsonb_agg(
        (c.data - 'reviews') || jsonb_build_object('reviews', coalesce(
          (select jsonb_agg(r - 'orderId' || case when r ? 'orderId' then '{"verified":true}'::jsonb else '{}'::jsonb end)
             from jsonb_array_elements(coalesce(c.data -> 'reviews', '[]'::jsonb)) r), '[]'::jsonb))
        order by c.pos, c.id) from public.coll c where c.coll = 'products' and c.data ->> 'status' <> 'hidden'), '[]'::jsonb),
    'slotUse', coalesce((select jsonb_object_agg(d, u) from (
        select day_t as d, jsonb_object_agg(time_t, n) as u from (
          select o.data ->> 'day' as day_t, o.data ->> 'time' as time_t, count(*) as n from public.orders o
           where o.data ? 'paidAt' and o.status <> 'cancelled' and o.data ->> 'day' >= to_char((now() at time zone public.shop_tz())::date - 1, 'YYYY-MM-DD')
           group by 1, 2) q group by day_t) q2), '{}'::jsonb),
    'sold', coalesce((select jsonb_object_agg(k, n) from (
        select i.key as k, sum((i.value)::int) as n
          from public.orders o, jsonb_each_text(o.data -> 'items') i
         where o.status in ('new','baking','ready','completed') and o.created_at > public.now_ms() - 90 * 86400000::bigint
         group by i.key) s), '{}'::jsonb),
    'coupons', coalesce((select jsonb_agg((c.data - 'maxUses') order by c.pos, c.id) from public.coll c
                         where c.coll = 'coupons' and coalesce((c.data ->> 'show')::boolean, false) and public.cp_live(c.data)), '[]'::jsonb)
  ) into res;
  return res;
end $$;

-- convert the saved settings once: build `slots` from the old `times`, and rewrite `times` as the switched-on boxes
do $$
declare st jsonb; slots jsonb := '[]'::jsonb; hrs int[] := '{}'; tm text; sm int; h int; lbl text; res jsonb;
begin
  select data into st from public.docs where key = 'settings';
  if st is null or jsonb_typeof(st -> 'slots') = 'array' then return; end if;
  for tm in select jsonb_array_elements_text(coalesce(st -> 'times', '[]'::jsonb)) loop
    sm := public.slot_start_min(tm);
    if sm is not null then hrs := hrs || (sm / 60); end if;
  end loop;
  if coalesce(array_length(hrs, 1), 0) = 0 then hrs := array[10]; end if;
  for h in 0..22 loop
    if h = any(hrs) then
      lbl := lpad(h::text, 2, '0') || ' to ' || lpad((h + 1)::text, 2, '0');
      slots := slots || jsonb_build_array(jsonb_build_object('t', lbl, 'on', true, 'limit', 0));
    end if;
  end loop;
  select coalesce(jsonb_agg(w ->> 't'), '[]'::jsonb) into res from jsonb_array_elements(slots) w where (w ->> 'on')::boolean;
  update public.docs set data = st || jsonb_build_object('slots', slots, 'times', res) where key = 'settings';
end $$;


-- ===== 20260117000000_gifts.sql =====
-- Callebrownies migration 17: "Gifts" promos in the Flash sales menu (free items with certain box sizes: always-given or a random pick).
-- Safe to run more than once. Run after migration 16.

-- gifts are not a price discount: keep them out of the sale price
create or replace function public.best_sale(p_n int, p_price numeric, p_at bigint) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare r jsonb;
begin
  select jsonb_build_object('id', s.data ->> 'id', 'name', s.data ->> 'name', 'discount', d,
           'text', (s.data ->> 'name') || ' (' ||
                   case when s.data ->> 'type' = 'percent' then (s.data ->> 'value') || '% off'
                        else public.money_txt((s.data ->> 'value')::numeric) || ' off' end || ')')
    into r
  from (select s2.data,
               case when s2.data ->> 'type' = 'percent'
                    then round(p_price * (s2.data ->> 'value')::numeric / 100, 2)
                    else round(least((s2.data ->> 'value')::numeric, p_price), 2) end as d
        from public.coll s2
        where s2.coll = 'sales' and coalesce(s2.data ->> 'type', '') not in ('freedelivery', 'gifts')
          and (s2.data ->> 'start')::bigint <= p_at and p_at < (s2.data ->> 'end')::bigint
          and (s2.data ->> 'appliesTo' = 'all' or (s2.data ->> 'appliesTo') = p_n::text)) s
  order by d desc limit 1;
  return r;
end $$;

-- the gifts a box of p_n brownies earns right now: every "always" gift, plus a random pick from each promo's "random" pool
create or replace function public.gifts_for(p_n int, p_at bigint) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare s record; g jsonb; res jsonb := '[]'::jsonb; q int; k int; cnt int;
begin
  for s in select c.data from public.coll c
           where c.coll = 'sales' and c.data ->> 'type' = 'gifts'
             and (c.data ->> 'start')::bigint <= p_at and p_at < (c.data ->> 'end')::bigint
             and (c.data ->> 'appliesTo' = 'all' or (c.data ->> 'appliesTo') = p_n::text)
           order by c.id loop
    for g in select value from jsonb_array_elements(coalesce(s.data -> 'gifts', '[]'::jsonb)) loop
      continue when btrim(coalesce(g ->> 'name', '')) = '';
      continue when coalesce(g ->> 'mode', 'fixed') = 'random';
      continue when jsonb_array_length(coalesce(g -> 'sizes', '[]'::jsonb)) > 0 and not (g -> 'sizes') @> to_jsonb(p_n);
      q := greatest(1, least(10, coalesce(nullif(g ->> 'qty', '')::numeric, 1)::int));
      res := res || jsonb_build_array(jsonb_build_object('id', g ->> 'id', 'name', left(g ->> 'name', 40), 'qty', q, 'promo', s.data ->> 'name'));
    end loop;
    cnt := greatest(1, least(5, coalesce(nullif(s.data ->> 'randomCount', '')::numeric, 1)::int));
    for g in select value from jsonb_array_elements(coalesce(s.data -> 'gifts', '[]'::jsonb)) as e(value)
             where btrim(coalesce(value ->> 'name', '')) <> '' and coalesce(value ->> 'mode', 'fixed') = 'random'
               and (jsonb_array_length(coalesce(value -> 'sizes', '[]'::jsonb)) = 0 or (value -> 'sizes') @> to_jsonb(p_n))
             order by random() limit cnt loop
      q := greatest(1, least(10, coalesce(nullif(g ->> 'qty', '')::numeric, 1)::int));
      res := res || jsonb_build_array(jsonb_build_object('id', g ->> 'id', 'name', left(g ->> 'name', 40), 'qty', q, 'promo', s.data ->> 'name', 'random', true));
    end loop;
  end loop;
  return res;
end $$;
revoke all on function public.gifts_for(int, bigint) from public, anon, authenticated;

create or replace function public.place_order(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  lim int; s jsonb := public.cfg(); t bigint := public.now_ms();
  v_size int; v_mode text; v_day text; v_time text; v_note text; v_notify text; v_coupon text; v_expect numeric;
  v_name text; v_email text; v_phone text; v_addr text; items jsonb := '{}'::jsonb; addon_ids jsonb := '[]'::jsonb;
  edit_id text := nullif(p ->> 'editId', ''); edit_tok text := p ->> 'editToken'; eo public.orders;
  k text; n int; total_items int := 0; prod record; surcharge numeric := 0; addons_total numeric := 0; a record; aid text;
  base numeric; sale jsonb; sd numeric := 0; cp jsonb; cdisc numeric := 0; fee numeric := 0; total numeric;
  win int := coalesce((s ->> 'payWindowH')::int, 24); today date; dte date; v_code text; oid text; tok text;
  v_speed text; lead numeric; sh int; earliest date; exp_ms bigint; smin int; startms bigint; minpay int; od jsonb; ms jsonb := '[]'::jsonb; msg text; ch text; sale_txt text := ''; gifts jsonb := '[]'::jsonb; tries int := 0; open_n int; own_stock int;
begin
  perform public.sweep_orders();
  if length(p::text) > 20000 then perform public.bad('That order is too large.'); end if;

  -- basic fields
  v_size := coalesce((p ->> 'size')::int, 0);
  v_mode := p ->> 'mode';        if v_mode not in ('pickup','delivery') then perform public.bad('Choose pickup or delivery.'); end if;
  v_speed := case when v_mode = 'pickup' then 'pickup' when p ->> 'speed' = 'sameday' then 'sameday' else 'scheduled' end;
  v_day := p ->> 'day';          v_time := p ->> 'time';
  v_note := left(coalesce(p ->> 'note', ''), 300);
  v_notify := coalesce(p ->> 'notify', 'both'); if v_notify not in ('whatsapp','email','both','none') then v_notify := 'both'; end if;
  v_coupon := upper(regexp_replace(coalesce(p ->> 'coupon', ''), '[^A-Za-z0-9_-]', '', 'g'));
  v_expect := nullif(p ->> 'expectTotal', '')::numeric;
  v_name  := btrim(coalesce(p #>> '{customer,name}', ''));
  v_email := btrim(coalesce(p #>> '{customer,email}', ''));
  v_phone := regexp_replace(coalesce(p #>> '{customer,phone}', ''), '\D', '', 'g');
  v_addr  := btrim(coalesce(p #>> '{customer,address}', ''));
  if length(v_name) < 1 or length(v_name) > 80 then perform public.bad('Please enter your name.'); end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 120 then perform public.bad('Please enter a valid email address.'); end if;
  if v_phone !~ '^\d{8,15}$' then perform public.bad('WhatsApp number: use numbers only, 8 to 15 digits.'); end if;
  if v_mode = 'delivery' then
    if length(v_addr) < 5 or length(v_addr) > 300 then perform public.bad('Please enter your delivery address.'); end if;
  else v_addr := ''; end if;

  -- schedule: pickup, scheduled delivery and sameday shipment each have an on/off switch and their own lead time
  today := (now() at time zone public.shop_tz())::date;
  sh := extract(hour from (now() at time zone public.shop_tz()))::int;
  if (v_speed = 'pickup' and not coalesce((s ->> 'pickupOn')::boolean, true))
     or (v_speed = 'scheduled' and not coalesce((s ->> 'schedOn')::boolean, true))
     or (v_speed = 'sameday' and not coalesce((s ->> 'samedayOn')::boolean, false)) then
    perform public.bad('That option isn''t available right now. Please choose another way to get your order.'); end if;
  if v_speed = 'sameday' then
    if sh >= coalesce((s ->> 'samedayCutoff')::int, 15) then
      perform public.bad('Sameday shipment is closed for today. Please choose another option.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from today)::int) then
      perform public.bad('We''re closed today. Please choose another option.'); end if;
    dte := today; v_day := today::text; v_time := 'Same day';
  else
    if v_day !~ '^\d{4}-\d{2}-\d{2}$' then perform public.bad('Please pick a day.'); end if;
    begin dte := v_day::date; exception when others then perform public.bad('Please pick a day.'); end;
    lead := greatest(0, least(720, coalesce((s ->> case v_speed when 'pickup' then 'pickupLeadH' else 'schedLeadH' end)::numeric, 24)));
    earliest := ((now() at time zone public.shop_tz()) + make_interval(hours => ceil(lead)::int))::date;
    if sh >= coalesce((s ->> 'cutoffHour')::int, 20) then earliest := earliest + 1; end if;
    if dte < earliest or dte > earliest + 6 then perform public.bad('Please pick another day.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from dte)::int) then
      perform public.bad('We''re closed that day. Please pick another day.'); end if;
    if not exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'times', '[]'::jsonb)) w where w = v_time) then
      perform public.bad('Please pick a time.'); end if;
    -- a time slot with a daily limit: only orders whose payment is confirmed use it up
    lim := coalesce((select (w ->> 'limit')::int from jsonb_array_elements(coalesce(s -> 'slots', '[]'::jsonb)) w where w ->> 't' = v_time limit 1), 0);
    if lim > 0 and (select count(*) from public.orders o2 where o2.data ->> 'day' = v_day and o2.data ->> 'time' = v_time
                      and o2.data ? 'paidAt' and o2.status <> 'cancelled' and o2.id is distinct from edit_id) >= lim then
      perform public.bad('Sorry, that time slot is full. Please pick another time.'); end if;
  end if;

  -- pay deadline: never later than (pickup/delivery time - lead time), and sameday orders get a short window
  minpay := greatest(1, coalesce((s ->> 'minPayMin')::int, 30));
  exp_ms := t + win * 3600000::bigint;
  if v_speed = 'sameday' then
    exp_ms := least(exp_ms, t + greatest(minpay, coalesce((s ->> 'samedayPayMin')::int, 60)) * 60000::bigint);
  else
    smin := public.slot_start_min(v_time);
    startms := (extract(epoch from ((dte + make_interval(mins => coalesce(smin, 540)))::timestamp at time zone public.shop_tz())) * 1000)::bigint;
    if smin is not null and startms < t + (lead * 3600000)::bigint + minpay * 60000::bigint then
      perform public.bad('That time is too soon for your order. Please pick a later time or day.'); end if;
    exp_ms := least(exp_ms, startms - (lead * 3600000)::bigint);
  end if;
  exp_ms := greatest(exp_ms, t + minpay * 60000::bigint);

  -- editing an existing unpaid order?
  if edit_id is not null then
    select * into eo from public.orders where id = edit_id for update;
    if not found or not exists (select 1 from public.order_tokens where order_id = edit_id and hash = public.tok_hash(edit_tok)) then
      perform public.bad('We couldn''t find that order.'); end if;
    if eo.status <> 'awaiting' then perform public.bad('This order can''t be edited any more.'); end if;
  else
    if not public.throttle_ok('order', 60, 60000) then perform public.bad('We''re very busy right now. Please try again in a minute.'); end if;
    select count(*) into open_n from public.orders where phone_norm = public.norm_phone(v_phone) and status = 'awaiting';
    if open_n >= 3 then perform public.bad('You already have 3 unpaid orders. Please pay or cancel one first.'); end if;
    if (select count(*) from public.orders where status = 'awaiting') >= coalesce((s ->> 'maxOpenOrders')::int, 150) then
      perform public.bad('We''re very busy right now. Please try again a little later.'); end if;
  end if;

  -- items
  if jsonb_typeof(p -> 'items') <> 'object' then perform public.bad('Your box is empty.'); end if;
  for k, n in select key, (value)::int from jsonb_each_text(p -> 'items') loop
    if n < 1 or n > 100 then perform public.bad('Please check your box.'); end if;
    items := items || jsonb_build_object(k, n); total_items := total_items + n;
  end loop;
  base := public.base_price(v_size);
  if base <= 0 then perform public.bad('That box size isn''t available.'); end if;
  if total_items <> v_size then perform public.bad('Please fill every spot in your box.'); end if;

  -- give back this order's own hold first, so stock checks see it
  if edit_id is not null and coalesce((eo.data ->> 'holds')::boolean, false) then
    for k, n in select key, value::int from jsonb_each_text(eo.data -> 'items') loop
      update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) + n)), updated_at = t
      where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
    end loop;
  end if;

  for k, n in select key, value::int from jsonb_each_text(items) order by key loop
    select * into prod from public.coll where coll = 'products' and id = k for update;
    if not found or prod.data ->> 'status' <> 'available' then
      perform public.bad('Sorry, ' || coalesce(prod.data ->> 'name', 'that flavor') || ' just sold out. Please change your box.'); end if;
    if coalesce((prod.data ->> 'track')::boolean, false) then
      own_stock := coalesce((prod.data ->> 'stock')::int, 0);
      if n > own_stock then
        perform public.bad(case when own_stock > 0 then 'Sorry, only ' || own_stock || ' ' || (prod.data ->> 'name') || ' left. Please change your box.'
                                else 'Sorry, ' || (prod.data ->> 'name') || ' just sold out. Please change your box.' end);
      end if;
    end if;
    surcharge := surcharge + coalesce((prod.data ->> 'surcharge')::numeric, 0) * n;
  end loop;
  surcharge := round(surcharge, 2);

  -- extras
  if jsonb_typeof(p -> 'addons') = 'array' then
    for aid in select distinct value from jsonb_array_elements_text(p -> 'addons') loop
      select * into a from public.coll where coll = 'addons' and id = aid;
      if found and coalesce((a.data ->> 'active')::boolean, true) then
        addons_total := addons_total + (a.data ->> 'price')::numeric; addon_ids := addon_ids || to_jsonb(aid);
      end if;
    end loop;
  end if;
  addons_total := round(addons_total, 2);

  -- sale + coupon + delivery fee
  sale := public.best_sale(v_size, base, t);
  if sale is not null then sd := (sale ->> 'discount')::numeric; sale_txt := sale ->> 'text'; end if;
  if edit_id is not null and eo.data ? 'gifts' and coalesce((eo.data ->> 'size')::int, -1) = v_size then gifts := eo.data -> 'gifts';
  else gifts := public.gifts_for(v_size, t); end if;
  if v_coupon <> '' then
    cp := public.cp_eval(v_coupon, v_size, v_phone, edit_id, base, sd);
    if not (cp ->> 'ok')::boolean then perform public.bad((cp ->> 'err') || ' Remove the coupon to continue.'); end if;
    cdisc := (cp ->> 'discount')::numeric;
  end if;
  if v_mode = 'delivery' and not coalesce((cp ->> 'freeDel')::boolean, false) and not public.free_del_live(v_size, t) then
    fee := case when v_speed = 'sameday' then coalesce((s ->> 'samedayFee')::numeric, (s ->> 'deliveryFee')::numeric, 0) else coalesce((s ->> 'deliveryFee')::numeric, 0) end; end if;
  total := round(base - sd - cdisc + surcharge + addons_total + fee, 2);
  if v_expect is not null and abs(v_expect - total) > 0.015 then
    perform public.bad('Prices changed while you were checking out. The new total is ' || public.money_txt(total) || '. Please review and place your order again.'); end if;

  -- take stock
  for k, n in select key, value::int from jsonb_each_text(items) loop
    update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) - n)), updated_at = t
    where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
  end loop;

  if edit_id is not null then
    od := eo.data || jsonb_build_object('notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time,
      'note', v_note, 'addons', addon_ids, 'sale', sale_txt, 'gifts', gifts, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc,
      'surcharge', surcharge, 'addonsTotal', addons_total, 'fee', fee, 'total', total, 'holds', true, 'tracked', true, 'editedAt', t,
      'shuffled', coalesce((p ->> 'shuffled')::boolean, false),
      'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr));
    update public.orders set data = od where id = edit_id;
    return jsonb_build_object('order', od);
  end if;

  loop
    v_code := 'DD-' || (select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', 1 + floor(random() * 32)::int, 1), '') from generate_series(1, 6));
    exit when not exists (select 1 from public.orders where orders.code = v_code);
    tries := tries + 1; if tries > 20 then perform public.bad('Please try again.'); end if;
  end loop;
  oid := substr(replace(gen_random_uuid()::text, '-', ''), 1, 16);
  tok := public.new_token();

  msg := 'Hi ' || coalesce(nullif(split_part(v_name, ' ', 1), ''), 'there') || ', your Callebrownies order ' || v_code || ' (' || public.money_txt(total)
         || ') is waiting for payment. Please pay and send your proof in My orders before it is cancelled automatically.';
  for ch in select unnest(case v_notify when 'both' then array['whatsapp','email'] when 'none' then array[]::text[] else array[v_notify] end) loop
    ms := ms || jsonb_build_array(jsonb_build_object('at', t, 'channel', ch, 'status', 'awaiting', 'text', msg, 'by', 'system'));
  end loop;

  od := jsonb_build_object('id', oid, 'code', v_code, 'tracked', true, 'holds', true, 'createdAt', t, 'expiresAt', exp_ms,
    'status', 'awaiting', 'notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time, 'note', v_note,
    'addons', addon_ids, 'sale', sale_txt, 'gifts', gifts, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc, 'surcharge', surcharge,
    'addonsTotal', addons_total, 'fee', fee, 'total', total, 'shuffled', coalesce((p ->> 'shuffled')::boolean, false),
    'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr), 'msgs', ms);
  insert into public.orders (id, code, status, phone_norm, created_at, updated_at, expires_at, data)
    values (oid, v_code, 'awaiting', public.norm_phone(v_phone), t, t, exp_ms, od);
  insert into public.order_tokens values (oid, public.tok_hash(tok), t);
  return jsonb_build_object('order', od, 'token', tok);
end $$;



-- ===== 20260118000000_biteship.sql =====
-- Callebrownies migration 18: optional Biteship courier delivery (rates at checkout, booking, tracking).
-- Safe to run more than once. Run after migration 17. Does nothing until the owner switches it on in Shop settings.

create table if not exists public.private_kv (
  key text primary key,
  data jsonb not null default '{}'::jsonb,
  updated_at bigint not null default 0
);
alter table public.private_kv enable row level security;
revoke all on public.private_kv from public, anon, authenticated;   -- only the owner functions below and the Edge Functions (service role) can touch it

insert into public.private_kv (key, data, updated_at)
  values ('quote_secret', jsonb_build_object('v', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '')), 0)
  on conflict (key) do nothing;
insert into public.private_kv (key, data, updated_at)
  values ('webhook_secret', jsonb_build_object('v', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '')), 0)
  on conflict (key) do nothing;

-- owner: read the (private) courier settings. The API key itself is never returned.
create or replace function public.admin_biteship_get() returns jsonb
language plpgsql security definer set search_path = public as $$
declare k text; c jsonb; w text;
begin
  perform public.assert_owner();
  select data ->> 'v' into k from public.private_kv where key = 'biteship_key';
  select data into c from public.private_kv where key = 'biteship_cfg';
  select data ->> 'v' into w from public.private_kv where key = 'webhook_secret';
  return jsonb_build_object('hasKey', k is not null and k <> '',
    'mode', case when k like 'biteship\_test%' then 'test' when k like 'biteship\_live%' then 'live' when k is null then '' else 'unknown' end,
    'cfg', coalesce(c, '{}'::jsonb), 'webhookSecret', coalesce(w, ''));
end $$;

-- owner: save the API key (p.key, empty text removes it) and/or the private courier settings (p.cfg)
create or replace function public.admin_biteship_save(p jsonb) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform public.assert_owner();
  if length(p::text) > 30000 then perform public.bad('That is too large.'); end if;
  if p ? 'key' then
    if btrim(coalesce(p ->> 'key', '')) = '' then delete from public.private_kv where key = 'biteship_key';
    else
      if length(btrim(p ->> 'key')) < 20 or length(btrim(p ->> 'key')) > 400 then perform public.bad('That does not look like a Biteship API key.'); end if;
      insert into public.private_kv (key, data, updated_at) values ('biteship_key', jsonb_build_object('v', btrim(p ->> 'key')), public.now_ms())
        on conflict (key) do update set data = excluded.data, updated_at = excluded.updated_at;
    end if;
  end if;
  if p ? 'cfg' then
    insert into public.private_kv (key, data, updated_at) values ('biteship_cfg', p -> 'cfg', public.now_ms())
      on conflict (key) do update set data = excluded.data, updated_at = excluded.updated_at;
  end if;
end $$;

-- who is calling: 'owner', 'staff' or '' (used by the Edge Function; does not write to the activity log)
create or replace function public.biteship_who() returns text
language plpgsql stable security definer set search_path = public as $$
declare me public.admins := public.team_me();
begin
  if me.email is null then return ''; end if;
  return coalesce(me.role, 'staff');
end $$;

-- checks a courier quote signed by the Edge Function (so nobody can invent a delivery price). Returns the safe fields, or null when none was sent.
create or replace function public.biteship_check(p_size int, p jsonb, p_at bigint) returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare secret text; msg text; price numeric; ex bigint;
begin
  if p is null or jsonb_typeof(p) <> 'object' or p = '{}'::jsonb then return null; end if;
  price := nullif(p ->> 'price', '')::numeric; ex := nullif(p ->> 'exp', '')::bigint;
  if price is null or ex is null or price < 0 or price > 5000000 or price <> trunc(price) then perform public.bad('That courier price is not valid. Please choose a courier again.'); end if;
  if coalesce((p ->> 'size')::int, -1) <> p_size then perform public.bad('The box size changed. Please choose a courier again.'); end if;
  select data ->> 'v' into secret from public.private_kv where key = 'quote_secret';
  msg := p_size::text || '|' || coalesce(p ->> 'courier', '') || '|' || coalesce(p ->> 'service', '') || '|' || price::bigint::text || '|' || ex::text
         || '|' || coalesce(p ->> 'lat', '') || '|' || coalesce(p ->> 'lng', '') || '|' || coalesce(p ->> 'postal', '');
  if secret is null or encode(hmac(msg, secret, 'sha256'), 'hex') <> coalesce(p ->> 'sig', '') then
    perform public.bad('That courier price is not valid. Please choose a courier again.'); end if;
  if p_at > ex then perform public.bad('The courier price expired. Please choose a courier again.'); end if;
  return jsonb_build_object('size', p_size, 'courier', left(p ->> 'courier', 30), 'service', left(p ->> 'service', 40),
    'courierName', left(coalesce(p ->> 'courierName', p ->> 'courier'), 40), 'serviceName', left(coalesce(p ->> 'serviceName', p ->> 'service'), 60),
    'type', left(coalesce(p ->> 'type', ''), 20), 'eta', left(coalesce(p ->> 'eta', ''), 30), 'price', price,
    'lat', p ->> 'lat', 'lng', p ->> 'lng', 'postal', left(coalesce(p ->> 'postal', ''), 12), 'areaId', left(coalesce(p ->> 'areaId', ''), 60),
    'areaName', left(coalesce(p ->> 'areaName', ''), 160), 'quotedAt', p_at);
end $$;

revoke all on function public.admin_biteship_get(), public.admin_biteship_save(jsonb), public.biteship_check(int, jsonb, bigint), public.biteship_who() from public, anon, authenticated;
grant execute on function public.admin_biteship_get(), public.admin_biteship_save(jsonb), public.biteship_who() to authenticated;

create or replace function public.place_order(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  lim int; s jsonb := public.cfg(); t bigint := public.now_ms();
  v_size int; v_mode text; v_day text; v_time text; v_note text; v_notify text; v_coupon text; v_expect numeric;
  v_name text; v_email text; v_phone text; v_addr text; items jsonb := '{}'::jsonb; addon_ids jsonb := '[]'::jsonb;
  edit_id text := nullif(p ->> 'editId', ''); edit_tok text := p ->> 'editToken'; eo public.orders;
  k text; n int; total_items int := 0; prod record; surcharge numeric := 0; addons_total numeric := 0; a record; aid text;
  base numeric; sale jsonb; sd numeric := 0; cp jsonb; cdisc numeric := 0; fee numeric := 0; total numeric;
  win int := coalesce((s ->> 'payWindowH')::int, 24); today date; dte date; v_code text; oid text; tok text;
  v_speed text; lead numeric; sh int; earliest date; exp_ms bigint; smin int; startms bigint; minpay int; od jsonb; ms jsonb := '[]'::jsonb; msg text; ch text; sale_txt text := ''; gifts jsonb := '[]'::jsonb; ship jsonb; tries int := 0; open_n int; own_stock int;
begin
  perform public.sweep_orders();
  if length(p::text) > 20000 then perform public.bad('That order is too large.'); end if;

  -- basic fields
  v_size := coalesce((p ->> 'size')::int, 0);
  v_mode := p ->> 'mode';        if v_mode not in ('pickup','delivery') then perform public.bad('Choose pickup or delivery.'); end if;
  v_speed := case when v_mode = 'pickup' then 'pickup' when p ->> 'speed' = 'sameday' then 'sameday' else 'scheduled' end;
  v_day := p ->> 'day';          v_time := p ->> 'time';
  v_note := left(coalesce(p ->> 'note', ''), 300);
  v_notify := coalesce(p ->> 'notify', 'both'); if v_notify not in ('whatsapp','email','both','none') then v_notify := 'both'; end if;
  v_coupon := upper(regexp_replace(coalesce(p ->> 'coupon', ''), '[^A-Za-z0-9_-]', '', 'g'));
  v_expect := nullif(p ->> 'expectTotal', '')::numeric;
  v_name  := btrim(coalesce(p #>> '{customer,name}', ''));
  v_email := btrim(coalesce(p #>> '{customer,email}', ''));
  v_phone := regexp_replace(coalesce(p #>> '{customer,phone}', ''), '\D', '', 'g');
  v_addr  := btrim(coalesce(p #>> '{customer,address}', ''));
  if length(v_name) < 1 or length(v_name) > 80 then perform public.bad('Please enter your name.'); end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 120 then perform public.bad('Please enter a valid email address.'); end if;
  if v_phone !~ '^\d{8,15}$' then perform public.bad('WhatsApp number: use numbers only, 8 to 15 digits.'); end if;
  if v_mode = 'delivery' then
    if length(v_addr) < 5 or length(v_addr) > 300 then perform public.bad('Please enter your delivery address.'); end if;
  else v_addr := ''; end if;

  -- schedule: pickup, scheduled delivery and sameday shipment each have an on/off switch and their own lead time
  today := (now() at time zone public.shop_tz())::date;
  sh := extract(hour from (now() at time zone public.shop_tz()))::int;
  if (v_speed = 'pickup' and not coalesce((s ->> 'pickupOn')::boolean, true))
     or (v_speed = 'scheduled' and not coalesce((s ->> 'schedOn')::boolean, true))
     or (v_speed = 'sameday' and not coalesce((s ->> 'samedayOn')::boolean, false)) then
    perform public.bad('That option isn''t available right now. Please choose another way to get your order.'); end if;
  if v_speed = 'sameday' then
    if sh >= coalesce((s ->> 'samedayCutoff')::int, 15) then
      perform public.bad('Sameday shipment is closed for today. Please choose another option.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from today)::int) then
      perform public.bad('We''re closed today. Please choose another option.'); end if;
    dte := today; v_day := today::text; v_time := 'Same day';
  else
    if v_day !~ '^\d{4}-\d{2}-\d{2}$' then perform public.bad('Please pick a day.'); end if;
    begin dte := v_day::date; exception when others then perform public.bad('Please pick a day.'); end;
    lead := greatest(0, least(720, coalesce((s ->> case v_speed when 'pickup' then 'pickupLeadH' else 'schedLeadH' end)::numeric, 24)));
    earliest := ((now() at time zone public.shop_tz()) + make_interval(hours => ceil(lead)::int))::date;
    if sh >= coalesce((s ->> 'cutoffHour')::int, 20) then earliest := earliest + 1; end if;
    if dte < earliest or dte > earliest + 6 then perform public.bad('Please pick another day.'); end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'closedWeekdays', '[]'::jsonb)) w where w::int = extract(dow from dte)::int) then
      perform public.bad('We''re closed that day. Please pick another day.'); end if;
    if not exists (select 1 from jsonb_array_elements_text(coalesce(s -> 'times', '[]'::jsonb)) w where w = v_time) then
      perform public.bad('Please pick a time.'); end if;
    -- a time slot with a daily limit: only orders whose payment is confirmed use it up
    lim := coalesce((select (w ->> 'limit')::int from jsonb_array_elements(coalesce(s -> 'slots', '[]'::jsonb)) w where w ->> 't' = v_time limit 1), 0);
    if lim > 0 and (select count(*) from public.orders o2 where o2.data ->> 'day' = v_day and o2.data ->> 'time' = v_time
                      and o2.data ? 'paidAt' and o2.status <> 'cancelled' and o2.id is distinct from edit_id) >= lim then
      perform public.bad('Sorry, that time slot is full. Please pick another time.'); end if;
  end if;

  -- pay deadline: never later than (pickup/delivery time - lead time), and sameday orders get a short window
  minpay := greatest(1, coalesce((s ->> 'minPayMin')::int, 30));
  exp_ms := t + win * 3600000::bigint;
  if v_speed = 'sameday' then
    exp_ms := least(exp_ms, t + greatest(minpay, coalesce((s ->> 'samedayPayMin')::int, 60)) * 60000::bigint);
  else
    smin := public.slot_start_min(v_time);
    startms := (extract(epoch from ((dte + make_interval(mins => coalesce(smin, 540)))::timestamp at time zone public.shop_tz())) * 1000)::bigint;
    if smin is not null and startms < t + (lead * 3600000)::bigint + minpay * 60000::bigint then
      perform public.bad('That time is too soon for your order. Please pick a later time or day.'); end if;
    exp_ms := least(exp_ms, startms - (lead * 3600000)::bigint);
  end if;
  exp_ms := greatest(exp_ms, t + minpay * 60000::bigint);

  -- editing an existing unpaid order?
  if edit_id is not null then
    select * into eo from public.orders where id = edit_id for update;
    if not found or not exists (select 1 from public.order_tokens where order_id = edit_id and hash = public.tok_hash(edit_tok)) then
      perform public.bad('We couldn''t find that order.'); end if;
    if eo.status <> 'awaiting' then perform public.bad('This order can''t be edited any more.'); end if;
  else
    if not public.throttle_ok('order', 60, 60000) then perform public.bad('We''re very busy right now. Please try again in a minute.'); end if;
    select count(*) into open_n from public.orders where phone_norm = public.norm_phone(v_phone) and status = 'awaiting';
    if open_n >= 3 then perform public.bad('You already have 3 unpaid orders. Please pay or cancel one first.'); end if;
    if (select count(*) from public.orders where status = 'awaiting') >= coalesce((s ->> 'maxOpenOrders')::int, 150) then
      perform public.bad('We''re very busy right now. Please try again a little later.'); end if;
  end if;

  -- items
  if jsonb_typeof(p -> 'items') <> 'object' then perform public.bad('Your box is empty.'); end if;
  for k, n in select key, (value)::int from jsonb_each_text(p -> 'items') loop
    if n < 1 or n > 100 then perform public.bad('Please check your box.'); end if;
    items := items || jsonb_build_object(k, n); total_items := total_items + n;
  end loop;
  base := public.base_price(v_size);
  if base <= 0 then perform public.bad('That box size isn''t available.'); end if;
  if total_items <> v_size then perform public.bad('Please fill every spot in your box.'); end if;

  -- give back this order's own hold first, so stock checks see it
  if edit_id is not null and coalesce((eo.data ->> 'holds')::boolean, false) then
    for k, n in select key, value::int from jsonb_each_text(eo.data -> 'items') loop
      update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) + n)), updated_at = t
      where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
    end loop;
  end if;

  for k, n in select key, value::int from jsonb_each_text(items) order by key loop
    select * into prod from public.coll where coll = 'products' and id = k for update;
    if not found or prod.data ->> 'status' <> 'available' then
      perform public.bad('Sorry, ' || coalesce(prod.data ->> 'name', 'that flavor') || ' just sold out. Please change your box.'); end if;
    if coalesce((prod.data ->> 'track')::boolean, false) then
      own_stock := coalesce((prod.data ->> 'stock')::int, 0);
      if n > own_stock then
        perform public.bad(case when own_stock > 0 then 'Sorry, only ' || own_stock || ' ' || (prod.data ->> 'name') || ' left. Please change your box.'
                                else 'Sorry, ' || (prod.data ->> 'name') || ' just sold out. Please change your box.' end);
      end if;
    end if;
    surcharge := surcharge + coalesce((prod.data ->> 'surcharge')::numeric, 0) * n;
  end loop;
  surcharge := round(surcharge, 2);

  -- extras
  if jsonb_typeof(p -> 'addons') = 'array' then
    for aid in select distinct value from jsonb_array_elements_text(p -> 'addons') loop
      select * into a from public.coll where coll = 'addons' and id = aid;
      if found and coalesce((a.data ->> 'active')::boolean, true) then
        addons_total := addons_total + (a.data ->> 'price')::numeric; addon_ids := addon_ids || to_jsonb(aid);
      end if;
    end loop;
  end if;
  addons_total := round(addons_total, 2);

  -- sale + coupon + delivery fee
  sale := public.best_sale(v_size, base, t);
  if sale is not null then sd := (sale ->> 'discount')::numeric; sale_txt := sale ->> 'text'; end if;
  if edit_id is not null and eo.data ? 'gifts' and coalesce((eo.data ->> 'size')::int, -1) = v_size then gifts := eo.data -> 'gifts';
  else gifts := public.gifts_for(v_size, t); end if;
  if v_coupon <> '' then
    cp := public.cp_eval(v_coupon, v_size, v_phone, edit_id, base, sd);
    if not (cp ->> 'ok')::boolean then perform public.bad((cp ->> 'err') || ' Remove the coupon to continue.'); end if;
    cdisc := (cp ->> 'discount')::numeric;
  end if;
  -- optional Biteship courier price: only when the owner switched it on and the customer picked a courier (signed quote)
  ship := null;
  if v_mode = 'delivery' and coalesce((s #>> '{biteship,on}')::boolean, false) then
    ship := public.biteship_check(v_size, p -> 'ship', t);
    if ship is null and not coalesce((s #>> '{biteship,fallback}')::boolean, true) then
      perform public.bad('Please choose a courier to see your delivery price.'); end if;
  end if;
  if v_mode = 'delivery' and not coalesce((cp ->> 'freeDel')::boolean, false) and not public.free_del_live(v_size, t) then
    if ship is not null then fee := (ship ->> 'price')::numeric;
    else fee := case when v_speed = 'sameday' then coalesce((s ->> 'samedayFee')::numeric, (s ->> 'deliveryFee')::numeric, 0) else coalesce((s ->> 'deliveryFee')::numeric, 0) end; end if;
  end if;
  total := round(base - sd - cdisc + surcharge + addons_total + fee, 2);
  if v_expect is not null and abs(v_expect - total) > 0.015 then
    perform public.bad('Prices changed while you were checking out. The new total is ' || public.money_txt(total) || '. Please review and place your order again.'); end if;

  -- take stock
  for k, n in select key, value::int from jsonb_each_text(items) loop
    update public.coll set data = jsonb_set(data, '{stock}', to_jsonb(coalesce((data ->> 'stock')::int, 0) - n)), updated_at = t
    where coll = 'products' and id = k and coalesce((data ->> 'track')::boolean, false);
  end loop;

  if edit_id is not null then
    od := eo.data || jsonb_build_object('notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time,
      'note', v_note, 'addons', addon_ids, 'sale', sale_txt, 'gifts', gifts, 'bship', ship, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc,
      'surcharge', surcharge, 'addonsTotal', addons_total, 'fee', fee, 'total', total, 'holds', true, 'tracked', true, 'editedAt', t,
      'shuffled', coalesce((p ->> 'shuffled')::boolean, false),
      'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr));
    update public.orders set data = od where id = edit_id;
    return jsonb_build_object('order', od);
  end if;

  loop
    v_code := 'DD-' || (select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', 1 + floor(random() * 32)::int, 1), '') from generate_series(1, 6));
    exit when not exists (select 1 from public.orders where orders.code = v_code);
    tries := tries + 1; if tries > 20 then perform public.bad('Please try again.'); end if;
  end loop;
  oid := substr(replace(gen_random_uuid()::text, '-', ''), 1, 16);
  tok := public.new_token();

  msg := 'Hi ' || coalesce(nullif(split_part(v_name, ' ', 1), ''), 'there') || ', your Callebrownies order ' || v_code || ' (' || public.money_txt(total)
         || ') is waiting for payment. Please pay and send your proof in My orders before it is cancelled automatically.';
  for ch in select unnest(case v_notify when 'both' then array['whatsapp','email'] when 'none' then array[]::text[] else array[v_notify] end) loop
    ms := ms || jsonb_build_array(jsonb_build_object('at', t, 'channel', ch, 'status', 'awaiting', 'text', msg, 'by', 'system'));
  end loop;

  od := jsonb_build_object('id', oid, 'code', v_code, 'tracked', true, 'holds', true, 'createdAt', t, 'expiresAt', exp_ms,
    'status', 'awaiting', 'notify', v_notify, 'size', v_size, 'items', items, 'mode', v_mode, 'speed', v_speed, 'day', v_day, 'time', v_time, 'note', v_note,
    'addons', addon_ids, 'sale', sale_txt, 'gifts', gifts, 'bship', ship, 'base', base, 'discount', sd, 'coupon', v_coupon, 'couponDisc', cdisc, 'surcharge', surcharge,
    'addonsTotal', addons_total, 'fee', fee, 'total', total, 'shuffled', coalesce((p ->> 'shuffled')::boolean, false),
    'customer', jsonb_build_object('name', v_name, 'email', v_email, 'phone', v_phone, 'address', v_addr), 'msgs', ms);
  insert into public.orders (id, code, status, phone_norm, created_at, updated_at, expires_at, data)
    values (oid, v_code, 'awaiting', public.norm_phone(v_phone), t, t, exp_ms, od);
  insert into public.order_tokens values (oid, public.tok_hash(tok), t);
  return jsonb_build_object('order', od, 'token', tok);
end $$;



-- ===== 20260119000000_google_geocode.sql =====
-- Callebrownies migration 19: optional Google Maps key for "Find my address on the map" (Biteship courier delivery).
-- Safe to run more than once. Run after migration 18.

create or replace function public.admin_biteship_get() returns jsonb
language plpgsql security definer set search_path = public as $$
declare k text; c jsonb; w text; g text;
begin
  perform public.assert_owner();
  select data ->> 'v' into k from public.private_kv where key = 'biteship_key';
  select data into c from public.private_kv where key = 'biteship_cfg';
  select data ->> 'v' into w from public.private_kv where key = 'webhook_secret';
  select data ->> 'v' into g from public.private_kv where key = 'google_key';
  return jsonb_build_object('hasKey', k is not null and k <> '',
    'mode', case when k like 'biteship\_test%' then 'test' when k like 'biteship\_live%' then 'live' when k is null then '' else 'unknown' end,
    'cfg', coalesce(c, '{}'::jsonb), 'webhookSecret', coalesce(w, ''), 'hasGoogle', g is not null and g <> '');
end $$;

create or replace function public.admin_biteship_save(p jsonb) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform public.assert_owner();
  if length(p::text) > 30000 then perform public.bad('That is too large.'); end if;
  if p ? 'key' then
    if btrim(coalesce(p ->> 'key', '')) = '' then delete from public.private_kv where key = 'biteship_key';
    else
      if length(btrim(p ->> 'key')) < 20 or length(btrim(p ->> 'key')) > 400 then perform public.bad('That does not look like a Biteship API key.'); end if;
      insert into public.private_kv (key, data, updated_at) values ('biteship_key', jsonb_build_object('v', btrim(p ->> 'key')), public.now_ms())
        on conflict (key) do update set data = excluded.data, updated_at = excluded.updated_at;
    end if;
  end if;
  if p ? 'gkey' then
    if btrim(coalesce(p ->> 'gkey', '')) = '' then delete from public.private_kv where key = 'google_key';
    else
      if btrim(p ->> 'gkey') !~ '^[A-Za-z0-9_-]{30,60}$' then perform public.bad('That does not look like a Google Maps API key.'); end if;
      insert into public.private_kv (key, data, updated_at) values ('google_key', jsonb_build_object('v', btrim(p ->> 'gkey')), public.now_ms())
        on conflict (key) do update set data = excluded.data, updated_at = excluded.updated_at;
    end if;
  end if;
  if p ? 'cfg' then
    insert into public.private_kv (key, data, updated_at) values ('biteship_cfg', p -> 'cfg', public.now_ms())
      on conflict (key) do update set data = excluded.data, updated_at = excluded.updated_at;
  end if;
end $$;

revoke all on function public.admin_biteship_get(), public.admin_biteship_save(jsonb) from public, anon, authenticated;
grant execute on function public.admin_biteship_get(), public.admin_biteship_save(jsonb) to authenticated;


-- ===== 20260120000000_place_photo.sql =====
-- Callebrownies migration 20: optional "Note for the driver" and "Photo of your place" for delivery orders.
-- Safe to run more than once. Run after migration 19. Switched on/off in the Delivery & courier tab.
-- The photo is kept out of the order (like payment proofs), only the shop and that customer can see it,
-- and it is deleted 3 days after the order is delivered or cancelled.

create or replace function public.place_cleanup() returns void
language sql security definer set search_path = public as $$
  delete from public.order_files f using public.orders o
  where f.kind = 'place' and o.id = f.order_id and o.status in ('completed','cancelled')
    and coalesce(nullif(o.data ->> 'completedAt', '')::bigint, o.updated_at) < public.now_ms() - 3 * 86400000::bigint;
$$;

-- customer: save the driver note and/or the place photo for their own order (p_img: data URL, '' keeps, 'remove' deletes)
create or replace function public.submit_place(p_id text, p_token text, p_note text, p_img text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders; s jsonb := public.cfg(); t bigint := public.now_ms(); d jsonb; nt text := left(btrim(coalesce(p_note, '')), 200); has boolean;
begin
  if not public.owns(p_id, p_token) then perform public.bad('We couldn''t find that order.'); end if;
  if not public.throttle_ok('place:' || p_id, 12, 3600000) then perform public.bad('Too many tries. Please wait a while.'); end if;
  select * into o from public.orders where id = p_id for update;
  if (o.data ->> 'mode') <> 'delivery' then perform public.bad('This order is not a delivery.'); end if;
  if o.status not in ('awaiting','review','new','baking') then perform public.bad('The courier is already on the way. Please contact the shop.'); end if;
  if not coalesce((s ->> 'dnoteOn')::boolean, true) then nt := coalesce(o.data #>> '{place,note}', ''); end if;
  if coalesce(p_img, '') = 'remove' then
    delete from public.order_files where order_id = p_id and kind = 'place';
  elsif coalesce(p_img, '') <> '' then
    if not coalesce((s ->> 'dphotoOn')::boolean, true) then perform public.bad('Photos are switched off.'); end if;
    if not public.valid_img(p_img) then perform public.bad('Please attach a photo (JPG, PNG or WebP, under 1 MB).'); end if;
    insert into public.order_files (order_id, kind, idx, data, at) values (p_id, 'place', 0, p_img, t)
      on conflict (order_id, kind, idx) do update set data = excluded.data, at = excluded.at;
  end if;
  has := exists (select 1 from public.order_files where order_id = p_id and kind = 'place');
  d := o.data || jsonb_build_object('place', jsonb_build_object('note', nt, 'photo', has, 'at', t));
  update public.orders set data = d where id = p_id;
  perform public.place_cleanup();
  return d;
end $$;

create or replace function public.order_files(p_id text, p_token text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.owns(p_id, p_token) then return '{}'::jsonb; end if;
  return jsonb_build_object(
    'proof', (select data from public.order_files where order_id = p_id and kind = 'proof' and idx = 0),
    'photos', coalesce((select jsonb_agg(data order by idx) from public.order_files where order_id = p_id and kind = 'complaint'), '[]'::jsonb),
    'place', (select data from public.order_files where order_id = p_id and kind = 'place' and idx = 0));
end $$;

create or replace function public.admin_order_files(p_id text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.assert_admin();
  if not (public.has_perm('orders') or public.has_perm('complaints')) then
    raise exception 'You don''t have access to orders. Ask the owner.' using errcode = '42501'; end if;
  return jsonb_build_object(
    'proof', (select data from public.order_files where order_id = p_id and kind = 'proof' and idx = 0),
    'photos', coalesce((select jsonb_agg(data order by idx) from public.order_files where order_id = p_id and kind = 'complaint'), '[]'::jsonb),
    'place', (select data from public.order_files where order_id = p_id and kind = 'place' and idx = 0));
end $$;

revoke all on function public.place_cleanup(), public.submit_place(text,text,text,text) from public, anon, authenticated;
grant execute on function public.submit_place(text,text,text,text) to anon, authenticated;
grant execute on function public.place_cleanup() to service_role;
revoke all on function public.order_files(text,text), public.admin_order_files(text) from public;
grant execute on function public.order_files(text,text) to anon, authenticated;
grant execute on function public.admin_order_files(text) to authenticated;


-- ===== 20260121000000_place_edit.sql =====
-- Callebrownies migration 21: customers can change the driver note / place photo until a courier is booked (not after).
-- Safe to run more than once. Run after migration 20.
create or replace function public.submit_place(p_id text, p_token text, p_note text, p_img text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders; s jsonb := public.cfg(); t bigint := public.now_ms(); d jsonb; nt text := left(btrim(coalesce(p_note, '')), 200); has boolean;
begin
  if not public.owns(p_id, p_token) then perform public.bad('We couldn''t find that order.'); end if;
  if not public.throttle_ok('place:' || p_id, 12, 3600000) then perform public.bad('Too many tries. Please wait a while.'); end if;
  select * into o from public.orders where id = p_id for update;
  if (o.data ->> 'mode') <> 'delivery' then perform public.bad('This order is not a delivery.'); end if;
  if o.status not in ('awaiting','review','new','baking') or coalesce(o.data #>> '{bship,biteshipId}', '') <> '' then
    perform public.bad('The courier is already booked, so the delivery details can''t change now. Please message the shop.'); end if;
  if not coalesce((s ->> 'dnoteOn')::boolean, true) then nt := coalesce(o.data #>> '{place,note}', ''); end if;
  if coalesce(p_img, '') = 'remove' then
    delete from public.order_files where order_id = p_id and kind = 'place';
  elsif coalesce(p_img, '') <> '' then
    if not coalesce((s ->> 'dphotoOn')::boolean, true) then perform public.bad('Photos are switched off.'); end if;
    if not public.valid_img(p_img) then perform public.bad('Please attach a photo (JPG, PNG or WebP, under 1 MB).'); end if;
    insert into public.order_files (order_id, kind, idx, data, at) values (p_id, 'place', 0, p_img, t)
      on conflict (order_id, kind, idx) do update set data = excluded.data, at = excluded.at;
  end if;
  has := exists (select 1 from public.order_files where order_id = p_id and kind = 'place');
  d := o.data || jsonb_build_object('place', jsonb_build_object('note', nt, 'photo', has, 'at', t));
  update public.orders set data = d where id = p_id;
  perform public.place_cleanup();
  return d;
end $$;
revoke all on function public.submit_place(text,text,text,text) from public, anon, authenticated;
grant execute on function public.submit_place(text,text,text,text) to anon, authenticated;


-- ===== 20260122000000_strict_steps.sql =====
-- Callebrownies migration 22: stricter order steps.
--  * a cancelled order can only be reopened at Awaiting payment / Check payment (never straight to Payment confirmed, Baking, Out for delivery or Delivered)
--  * a paid order (Baking and later) can't be moved back to the payment steps; Payment confirmed can go back to Check payment (undo), which clears the paid mark
-- Safe to run more than once. Run after migration 21.

create or replace function public.admin_patch_order(p_id text, p_patch jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders; d jsonb; pt jsonb := coalesce(p_patch, '{}'::jsonb); me public.admins := public.team_me();
        owner boolean; cur text; st text; deliv boolean; only_cp boolean; courier text; awb text; k text;
        parts text[] := '{}'; ask boolean := false; approved boolean := false; askrej boolean := false; rrsn text; sl text[][] := array[
  ['awaiting','Awaiting payment'],['review','Check payment'],['new','Payment confirmed'],['baking','Baking'],['ready','Ready / out for delivery'],['completed','Delivered / picked up'],['cancelled','Cancelled']];
  nm_old text; nm_new text; i int;
begin
  perform public.assert_admin();
  owner := me.role = 'owner';
  only_cp := not exists (select 1 from jsonb_object_keys(pt) x where x not in ('complaint','msgsAdd'));
  if not (public.has_perm('orders') or (only_cp and public.has_perm('complaints'))) then
    raise exception 'You don''t have access to change orders. Ask the owner.' using errcode = '42501'; end if;
  select * into o from public.orders where id = p_id for update;
  if not found then perform public.bad('Order not found'); end if;
  cur := o.status; deliv := (o.data ->> 'mode') = 'delivery';
  st := nullif(pt ->> 'status', ''); if st = cur then st := null; pt := pt - 'status'; end if;

  -- owner turns down a staff member's proof rejection (the order stays at Check payment)
  if pt ? 'rejReqReject' then
    if not owner then perform public.bad('Only an owner can approve or turn down a payment.'); end if;
    pt := pt - 'rejReqReject';
    if o.data ? 'rejReq' then
      perform set_config('dd.op', 'order', true);
      update public.orders set data = data - 'rejReq' where id = p_id;
      perform public.log_act('Order ' || coalesce(o.data ->> 'code', p_id), 'proof rejection turned down');
      select * into o from public.orders where id = p_id;
    end if;
    if pt = '{}'::jsonb then return o.data; end if;
  end if;

  -- owner turns down a staff member's payment confirmation
  if pt ? 'payReqReject' then
    if not owner then perform public.bad('Only an owner can approve or turn down a payment.'); end if;
    pt := pt - 'payReqReject';
    if o.data ? 'payReq' then
      perform set_config('dd.op', 'order', true);
      update public.orders set data = data - 'payReq' where id = p_id;
      perform public.log_act('Order ' || coalesce(o.data ->> 'code', p_id), 'payment approval turned down');
      select * into o from public.orders where id = p_id;
    end if;
    if pt = '{}'::jsonb then return o.data; end if;
  end if;

  -- typing courier + airway bill on a baking delivery order sends it out
  courier := btrim(coalesce(case when pt ? 'courier' then pt ->> 'courier' else o.data ->> 'courier' end, ''));
  awb     := btrim(coalesce(case when pt ? 'awb' then pt ->> 'awb' else o.data ->> 'awb' end, ''));
  if st is null and deliv and cur = 'baking' and (pt ? 'courier' or pt ? 'awb') and courier <> '' and awb <> '' then
    st := 'ready'; pt := jsonb_set(pt, '{status}', to_jsonb(st));
  end if;

  if st is not null then
    -- payment comes first: a cancelled order is only reopened at the payment steps, and a paid order never goes back to them
    if cur = 'cancelled' and st not in ('awaiting','review') then
      perform public.bad('A cancelled order can only be reopened as Awaiting payment (or Check payment if it has a proof). Then confirm the payment again.'); end if;
    if st = 'review' and not (o.data ? 'proof') then
      perform public.bad('Check payment needs the customer''s payment proof first.'); end if;
    if cur in ('baking','ready','completed') and st in ('awaiting','review') then
      perform public.bad('This order is already paid. Use Cancel order or Refund instead of moving it back to payment.'); end if;
    if cur = 'new' and st = 'awaiting' then
      perform public.bad('To undo a payment confirmation, move it back to Check payment.'); end if;
    if st in ('awaiting','review') then pt := pt || jsonb_build_object('paidAt', null); end if;   -- no longer counted as paid
    if st = 'new' and not (o.data ? 'proof') then
      perform public.bad('Confirm payment needs the customer''s payment proof first.'); end if;
    if st = 'ready' and deliv and (courier = '' or awb = '') then
      perform public.bad('Type the courier and the airway bill number first. The order moves to Out for delivery by itself.'); end if;
    -- order of steps: nobody can skip one, and nothing moves on before the payment is confirmed
    declare ci int := array_position(array['awaiting','review','new','baking','ready','completed'], cur);
            si int := array_position(array['awaiting','review','new','baking','ready','completed'], st);
    begin
      if st = 'new' and ci is not null and ci < 3 and cur <> 'review' then
        perform public.bad('Confirm payment needs the customer''s payment proof first (the order must be at Check payment).'); end if;
      if si is not null and ci is not null and si > 3 and ci < 3 then
        perform public.bad('Confirm the payment first. Orders can''t skip steps.'); end if;
      if si is not null and ci is not null and ci >= 3 and si > ci + 1 then
        perform public.bad('Orders move one step at a time. They can''t skip a step.'); end if;
    end;
    if not owner then
      if cur = 'review' and st = 'new' then
        if o.data ? 'rejReq' then perform public.bad('A proof rejection is already waiting for the owner.'); end if;
        ask := true;
      elsif cur = 'review' and st = 'awaiting' then
        if o.data ? 'payReq' then perform public.bad('A payment confirmation is already waiting for the owner.'); end if;
        askrej := true;
      elsif not ((cur in ('awaiting','review') and st = 'cancelled')
              or (cur = 'new' and st = 'baking')
              or (cur = 'baking' and st = 'ready')
              or (cur = 'ready' and st = 'completed')) then
        perform public.bad('Orders only move forward one step at a time. Going back or cancelling a paid order needs an owner.');
      end if;
    end if;
  end if;

  -- staff can't edit an order that is ready or done (adding a missing airway bill is fine)
  if not owner and cur in ('new','baking','ready','completed','cancelled') then
    for k in select jsonb_object_keys(pt) loop
      if k in ('items','total','surcharge','notify','expiresAt','cancelReason','paidAt','rejected')
         or (k in ('courier','awb') and btrim(coalesce(o.data ->> k, '')) <> '' and (pt ->> k) is distinct from (o.data ->> k)) then
        perform public.bad('This order is ' || case cur when 'new' then 'paid' when 'baking' then 'paid' when 'ready' then 'ready' when 'completed' then 'done' else 'cancelled' end || '. Only an owner can change it now.');
      end if;
    end loop;
  end if;
  if not owner and cur in ('new','baking') and st = 'cancelled' then
    perform public.bad('Only an owner can cancel a paid order.'); end if;

  if askrej then rrsn := left(btrim(coalesce(pt #>> '{rejected,reason}', '')), 80); pt := pt - 'status' - 'rejected' - 'expiresAt'; end if;
  if ask then pt := pt - 'status' - 'paidAt'; end if;
  perform set_config('dd.op', 'order', true);
  if pt <> '{}'::jsonb then d := public.admin_patch_order_core(p_id, pt); else d := o.data; end if;

  if ask then
    d := d || jsonb_build_object('payReq', jsonb_build_object('by', coalesce(nullif(me.name, ''), me.username, me.email), 'role', coalesce(nullif(me.title, ''), 'Staff'), 'at', public.now_ms()));
    update public.orders set data = d where id = p_id;
    perform public.log_act('Order ' || coalesce(d ->> 'code', p_id), 'payment checked, waiting for owner approval');
  elsif askrej then
    d := d || jsonb_build_object('rejReq', jsonb_build_object('by', coalesce(nullif(me.name, ''), me.username, me.email), 'role', coalesce(nullif(me.title, ''), 'Staff'), 'at', public.now_ms(), 'reason', rrsn));
    update public.orders set data = d where id = p_id;
    perform public.log_act('Order ' || coalesce(d ->> 'code', p_id), 'proof rejected, waiting for owner approval' || case when rrsn <> '' then ' (' || rrsn || ')' else '' end);
  elsif (d ->> 'status') = 'new' and d ? 'payReq' then
    approved := true; d := d - 'payReq';
    update public.orders set data = d where id = p_id;
  elsif (d ->> 'status') <> 'review' and d ? 'payReq' then
    d := d - 'payReq'; update public.orders set data = d where id = p_id;
  end if;

  if (d ->> 'status') <> 'review' and d ? 'rejReq' then d := d - 'rejReq'; update public.orders set data = d where id = p_id; end if;

  if (o.data ->> 'status') is distinct from (d ->> 'status') then
    for i in 1 .. array_length(sl, 1) loop
      if sl[i][1] = o.data ->> 'status' then nm_old := sl[i][2]; end if;
      if sl[i][1] = d ->> 'status' then nm_new := sl[i][2]; end if;
    end loop;
    parts := parts || ('status ' || coalesce(nm_old, o.data ->> 'status') || ' → ' || coalesce(nm_new, d ->> 'status'));
  end if;
  if approved then parts := parts || 'payment approved'::text; end if;
  if (o.data -> 'items') is distinct from (d -> 'items') then parts := parts || 'brownies changed'::text; end if;
  if (o.data ->> 'courier') is distinct from (d ->> 'courier') or (o.data ->> 'awb') is distinct from (d ->> 'awb') then
    parts := parts || ('courier ' || coalesce(d ->> 'courier', '') || ' ' || coalesce(d ->> 'awb', '')); end if;
  if (o.data #>> '{complaint,status}') is distinct from (d #>> '{complaint,status}') then parts := parts || ('complaint ' || coalesce(d #>> '{complaint,status}', '')); end if;
  if (o.data #>> '{complaint,reply}') is distinct from (d #>> '{complaint,reply}') then parts := parts || 'complaint reply'::text; end if;
  if (o.data -> 'rejected') is distinct from (d -> 'rejected') and d ? 'rejected' then parts := parts || 'payment proof rejected'::text; end if;
  if array_length(parts, 1) > 0 then perform public.log_act('Order ' || coalesce(d ->> 'code', p_id), array_to_string(parts, ', ')); end if;
  return d;
end $$;



-- ===== 20260123000000_owner_mode.sql =====
-- Callebrownies migration 23: Owner mode per order.
-- Owner overrides (going back a step, cancelling a paid order, reopening a cancelled one, editing a paid order,
-- changing a set courier / airway bill, refunds) only work after the owner turns on Owner mode for that order
-- with the owner password. It switches itself off after 5 minutes. Everyday work (confirming payments,
-- approving staff requests, moving forward) works as before. Safe to run more than once. Run after migration 22.

create table if not exists public.order_unlock (
  order_id text not null, email text not null, until bigint not null,
  primary key (order_id, email)
);
alter table public.order_unlock enable row level security;
revoke all on public.order_unlock from public, anon, authenticated;

create or replace function public.owner_unlocked(p_id text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.order_unlock u
                 where u.order_id = p_id and u.email = lower(coalesce(auth.jwt() ->> 'email', '')) and u.until > public.now_ms())
$$;

-- owner: turn Owner mode on for one order (5 minutes); p_password empty = turn it off
create or replace function public.admin_owner_mode(p_id text, p_password text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me public.admins := public.team_me(); em text := lower(coalesce(auth.jwt() ->> 'email', '')); u bigint := public.now_ms() + 300000; c text;
begin
  perform public.assert_admin();
  if me.role is distinct from 'owner' then perform public.bad('Only an owner can use Owner mode.'); end if;
  select data ->> 'code' into c from public.orders where id = p_id;
  if c is null then perform public.bad('Order not found'); end if;
  if coalesce(p_password, '') = '' then
    delete from public.order_unlock where order_id = p_id and email = em;
    return jsonb_build_object('ok', true, 'until', 0);
  end if;
  if not public.throttle_ok('sudo:' || em, 8, 600000) then
    return jsonb_build_object('ok', false, 'err', 'Too many tries. Please wait 10 minutes.'); end if;
  if not public.owner_pw_ok(p_password) then
    perform public.log_act('Owner password wrong', 'Owner mode on order ' || c);
    return jsonb_build_object('ok', false, 'err', 'That owner password isn''t right.'); end if;
  delete from public.order_unlock where until < public.now_ms();
  insert into public.order_unlock (order_id, email, until) values (p_id, em, u)
    on conflict (order_id, email) do update set until = excluded.until;
  perform public.log_act('Owner mode on: order ' || c, 'for 5 minutes');
  return jsonb_build_object('ok', true, 'until', u);
end $$;

revoke all on function public.owner_unlocked(text), public.admin_owner_mode(text, text) from public, anon, authenticated;
grant execute on function public.admin_owner_mode(text, text) to authenticated;

create or replace function public.admin_patch_order(p_id text, p_patch jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders; d jsonb; pt jsonb := coalesce(p_patch, '{}'::jsonb); me public.admins := public.team_me();
        owner boolean; cur text; st text; deliv boolean; only_cp boolean; courier text; awb text; k text;
        parts text[] := '{}'; ask boolean := false; approved boolean := false; askrej boolean := false; rrsn text; sl text[][] := array[
  ['awaiting','Awaiting payment'],['review','Check payment'],['new','Payment confirmed'],['baking','Baking'],['ready','Ready / out for delivery'],['completed','Delivered / picked up'],['cancelled','Cancelled']];
  nm_old text; nm_new text; i int; ovr boolean;
begin
  perform public.assert_admin();
  owner := me.role = 'owner';
  ovr := owner and public.owner_unlocked(p_id);   -- Owner mode switched on for this order (password, 5 minutes)
  only_cp := not exists (select 1 from jsonb_object_keys(pt) x where x not in ('complaint','msgsAdd'));
  if not (public.has_perm('orders') or (only_cp and public.has_perm('complaints'))) then
    raise exception 'You don''t have access to change orders. Ask the owner.' using errcode = '42501'; end if;
  select * into o from public.orders where id = p_id for update;
  if not found then perform public.bad('Order not found'); end if;
  cur := o.status; deliv := (o.data ->> 'mode') = 'delivery';
  st := nullif(pt ->> 'status', ''); if st = cur then st := null; pt := pt - 'status'; end if;

  -- owner turns down a staff member's proof rejection (the order stays at Check payment)
  if pt ? 'rejReqReject' then
    if not owner then perform public.bad('Only an owner can approve or turn down a payment.'); end if;
    pt := pt - 'rejReqReject';
    if o.data ? 'rejReq' then
      perform set_config('dd.op', 'order', true);
      update public.orders set data = data - 'rejReq' where id = p_id;
      perform public.log_act('Order ' || coalesce(o.data ->> 'code', p_id), 'proof rejection turned down');
      select * into o from public.orders where id = p_id;
    end if;
    if pt = '{}'::jsonb then return o.data; end if;
  end if;

  -- owner turns down a staff member's payment confirmation
  if pt ? 'payReqReject' then
    if not owner then perform public.bad('Only an owner can approve or turn down a payment.'); end if;
    pt := pt - 'payReqReject';
    if o.data ? 'payReq' then
      perform set_config('dd.op', 'order', true);
      update public.orders set data = data - 'payReq' where id = p_id;
      perform public.log_act('Order ' || coalesce(o.data ->> 'code', p_id), 'payment approval turned down');
      select * into o from public.orders where id = p_id;
    end if;
    if pt = '{}'::jsonb then return o.data; end if;
  end if;

  -- typing courier + airway bill on a baking delivery order sends it out
  courier := btrim(coalesce(case when pt ? 'courier' then pt ->> 'courier' else o.data ->> 'courier' end, ''));
  awb     := btrim(coalesce(case when pt ? 'awb' then pt ->> 'awb' else o.data ->> 'awb' end, ''));
  if st is null and deliv and cur = 'baking' and (pt ? 'courier' or pt ? 'awb') and courier <> '' and awb <> '' then
    st := 'ready'; pt := jsonb_set(pt, '{status}', to_jsonb(st));
  end if;

  if st is not null then
    -- payment comes first: a cancelled order is only reopened at the payment steps, and a paid order never goes back to them
    if cur = 'cancelled' and st not in ('awaiting','review') then
      perform public.bad('A cancelled order can only be reopened as Awaiting payment (or Check payment if it has a proof). Then confirm the payment again.'); end if;
    if st = 'review' and not (o.data ? 'proof') then
      perform public.bad('Check payment needs the customer''s payment proof first.'); end if;
    if cur in ('baking','ready','completed') and st in ('awaiting','review') then
      perform public.bad('This order is already paid. Use Cancel order or Refund instead of moving it back to payment.'); end if;
    if cur = 'new' and st = 'awaiting' then
      perform public.bad('To undo a payment confirmation, move it back to Check payment.'); end if;
    if st in ('awaiting','review') then pt := pt || jsonb_build_object('paidAt', null); end if;   -- no longer counted as paid
    if st = 'new' and not (o.data ? 'proof') then
      perform public.bad('Confirm payment needs the customer''s payment proof first.'); end if;
    if st = 'ready' and deliv and (courier = '' or awb = '') then
      perform public.bad('Type the courier and the airway bill number first. The order moves to Out for delivery by itself.'); end if;
    -- order of steps: nobody can skip one, and nothing moves on before the payment is confirmed
    declare ci int := array_position(array['awaiting','review','new','baking','ready','completed'], cur);
            si int := array_position(array['awaiting','review','new','baking','ready','completed'], st);
    begin
      if st = 'new' and ci is not null and ci < 3 and cur <> 'review' then
        perform public.bad('Confirm payment needs the customer''s payment proof first (the order must be at Check payment).'); end if;
      if si is not null and ci is not null and si > 3 and ci < 3 then
        perform public.bad('Confirm the payment first. Orders can''t skip steps.'); end if;
      if si is not null and ci is not null and ci >= 3 and si > ci + 1 then
        perform public.bad('Orders move one step at a time. They can''t skip a step.'); end if;
    end;
    -- everyday rules for everybody; going back, cancelling a paid order or reopening a cancelled one needs Owner mode on this order
    if not ovr then
      if cur = 'review' and st = 'new' then
        if not owner then
          if o.data ? 'rejReq' then perform public.bad('A proof rejection is already waiting for the owner.'); end if;
          ask := true;
        end if;
      elsif cur = 'review' and st = 'awaiting' then
        if not owner then
          if o.data ? 'payReq' then perform public.bad('A payment confirmation is already waiting for the owner.'); end if;
          askrej := true;
        end if;
      elsif not ((cur in ('awaiting','review') and st = 'cancelled')
              or (cur = 'new' and st = 'baking')
              or (cur = 'baking' and st = 'ready')
              or (cur = 'ready' and st = 'completed')) then
        perform public.bad(case when owner then 'Turn on Owner mode for this order first (going back a step, cancelling a paid order or reopening a cancelled one).'
                                else 'Orders only move forward one step at a time. Going back or cancelling a paid order needs an owner.' end);
      end if;
    end if;
  end if;

  -- staff can't edit an order that is ready or done (adding a missing airway bill is fine)
  -- after payment the order itself is locked (a missing airway bill can still be added); the owner unlocks it with Owner mode
  if not ovr and cur in ('new','baking','ready','completed','cancelled') then
    for k in select jsonb_object_keys(pt) loop
      if (k in ('items','total','surcharge','notify','expiresAt','cancelReason','rejected') or (k = 'paidAt' and not (st in ('awaiting','review'))))
         or (k in ('courier','awb') and btrim(coalesce(o.data ->> k, '')) <> '' and (pt ->> k) is distinct from (o.data ->> k)) then
        perform public.bad(case when owner then 'This order is locked after payment. Turn on Owner mode for this order to change it.'
          else 'This order is ' || case cur when 'new' then 'paid' when 'baking' then 'paid' when 'ready' then 'ready' when 'completed' then 'done' else 'cancelled' end || '. Only an owner can change it now.' end);
      end if;
    end loop;
  end if;
  if not ovr and cur in ('new','baking','ready','completed') and st = 'cancelled' then
    perform public.bad(case when owner then 'Turn on Owner mode for this order to cancel a paid order.' else 'Only an owner can cancel a paid order.' end); end if;
  if ovr and (st is not null or pt ?| array['items','total','surcharge','notify','expiresAt','cancelReason','courier','awb']) then
    perform public.log_act('Owner mode: order ' || coalesce(o.data ->> 'code', p_id), 'override used'); end if;

  if askrej then rrsn := left(btrim(coalesce(pt #>> '{rejected,reason}', '')), 80); pt := pt - 'status' - 'rejected' - 'expiresAt'; end if;
  if ask then pt := pt - 'status' - 'paidAt'; end if;
  perform set_config('dd.op', 'order', true);
  if pt <> '{}'::jsonb then d := public.admin_patch_order_core(p_id, pt); else d := o.data; end if;

  if ask then
    d := d || jsonb_build_object('payReq', jsonb_build_object('by', coalesce(nullif(me.name, ''), me.username, me.email), 'role', coalesce(nullif(me.title, ''), 'Staff'), 'at', public.now_ms()));
    update public.orders set data = d where id = p_id;
    perform public.log_act('Order ' || coalesce(d ->> 'code', p_id), 'payment checked, waiting for owner approval');
  elsif askrej then
    d := d || jsonb_build_object('rejReq', jsonb_build_object('by', coalesce(nullif(me.name, ''), me.username, me.email), 'role', coalesce(nullif(me.title, ''), 'Staff'), 'at', public.now_ms(), 'reason', rrsn));
    update public.orders set data = d where id = p_id;
    perform public.log_act('Order ' || coalesce(d ->> 'code', p_id), 'proof rejected, waiting for owner approval' || case when rrsn <> '' then ' (' || rrsn || ')' else '' end);
  elsif (d ->> 'status') = 'new' and d ? 'payReq' then
    approved := true; d := d - 'payReq';
    update public.orders set data = d where id = p_id;
  elsif (d ->> 'status') <> 'review' and d ? 'payReq' then
    d := d - 'payReq'; update public.orders set data = d where id = p_id;
  end if;

  if (d ->> 'status') <> 'review' and d ? 'rejReq' then d := d - 'rejReq'; update public.orders set data = d where id = p_id; end if;

  if (o.data ->> 'status') is distinct from (d ->> 'status') then
    for i in 1 .. array_length(sl, 1) loop
      if sl[i][1] = o.data ->> 'status' then nm_old := sl[i][2]; end if;
      if sl[i][1] = d ->> 'status' then nm_new := sl[i][2]; end if;
    end loop;
    parts := parts || ('status ' || coalesce(nm_old, o.data ->> 'status') || ' → ' || coalesce(nm_new, d ->> 'status'));
  end if;
  if approved then parts := parts || 'payment approved'::text; end if;
  if (o.data -> 'items') is distinct from (d -> 'items') then parts := parts || 'brownies changed'::text; end if;
  if (o.data ->> 'courier') is distinct from (d ->> 'courier') or (o.data ->> 'awb') is distinct from (d ->> 'awb') then
    parts := parts || ('courier ' || coalesce(d ->> 'courier', '') || ' ' || coalesce(d ->> 'awb', '')); end if;
  if (o.data #>> '{complaint,status}') is distinct from (d #>> '{complaint,status}') then parts := parts || ('complaint ' || coalesce(d #>> '{complaint,status}', '')); end if;
  if (o.data #>> '{complaint,reply}') is distinct from (d #>> '{complaint,reply}') then parts := parts || 'complaint reply'::text; end if;
  if (o.data -> 'rejected') is distinct from (d -> 'rejected') and d ? 'rejected' then parts := parts || 'payment proof rejected'::text; end if;
  if array_length(parts, 1) > 0 then perform public.log_act('Order ' || coalesce(d ->> 'code', p_id), array_to_string(parts, ', ')); end if;
  return d;
end $$;

create or replace function public.admin_refund_order(p_id text, p_amount numeric, p_note text, p_msgs jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders; me public.admins := public.team_me(); amt numeric; tot numeric; d jsonb; m jsonb; t bigint := public.now_ms(); ms jsonb;
begin
  perform public.assert_admin();
  if me.role is distinct from 'owner' then perform public.bad('Only an owner can refund an order.'); end if;
  if not public.owner_unlocked(p_id) then perform public.bad('Turn on Owner mode for this order to refund it.'); end if;
  select * into o from public.orders where id = p_id for update;
  if not found then perform public.bad('Order not found'); end if;
  if not (o.data ? 'paidAt') then perform public.bad('Only an order that was paid can be refunded.'); end if;
  if o.data ? 'refund' then perform public.bad('This order is already marked as refunded.'); end if;
  tot := coalesce((o.data ->> 'total')::numeric, 0);
  amt := round(coalesce(p_amount, tot), 2);
  if amt <= 0 or amt > tot then perform public.bad('The refund must be more than 0 and no more than the order total.'); end if;
  ms := coalesce(o.data -> 'msgs', '[]'::jsonb);
  if jsonb_typeof(p_msgs) = 'array' then
    for m in select * from jsonb_array_elements(p_msgs) loop
      if m ->> 'channel' in ('whatsapp', 'email') and btrim(coalesce(m ->> 'text', '')) <> '' then
        ms := ms || jsonb_build_array(jsonb_build_object('at', t, 'channel', m ->> 'channel', 'status', 'refunded', 'text', left(m ->> 'text', 800), 'by', 'staff'));
      end if;
    end loop;
  end if;
  d := o.data || jsonb_build_object('msgs', ms, 'refund', jsonb_build_object(
         'amount', amt, 'full', amt >= tot, 'at', t, 'note', left(btrim(coalesce(p_note, '')), 200),
         'by', coalesce(nullif(me.name, ''), me.username, me.email)));
  perform set_config('dd.op', 'order', true);
  update public.orders set data = d, updated_at = t where id = p_id;
  perform public.log_act('Order ' || coalesce(d ->> 'code', p_id), 'refunded ' || amt::text || case when amt >= tot then ' (full)' else ' (part)' end);
  return d;
end $$;


-- ===== 20260124000000_refund_proof.sql =====
-- Callebrownies migration 24: a refund needs a picture proof (the transfer receipt / screenshot).
--  * the picture is kept out of the order (like payment proofs) in order_files, kind 'refund'; the order only keeps refund.proof = true
--  * admin_refund_order now takes the picture and refuses to save a refund without it (the old 4-argument version is removed)
--  * admin_order_files also returns the refund picture
--  * also allows kind 'place' in order_files (the driver place photo of migrations 20 and 21 uses it)
-- Safe to run more than once. Run after migration 23.

do $$ begin
  alter table public.order_files drop constraint if exists order_files_kind_check;
  alter table public.order_files add constraint order_files_kind_check check (kind in ('proof','complaint','place','refund'));
end $$;

drop function if exists public.admin_refund_order(text, numeric, text, jsonb);
create or replace function public.admin_refund_order(p_id text, p_amount numeric, p_note text, p_msgs jsonb, p_img text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders; me public.admins := public.team_me(); amt numeric; tot numeric; d jsonb; m jsonb; t bigint := public.now_ms(); ms jsonb;
begin
  perform public.assert_admin();
  if me.role is distinct from 'owner' then perform public.bad('Only an owner can refund an order.'); end if;
  if not public.owner_unlocked(p_id) then perform public.bad('Turn on Owner mode for this order to refund it.'); end if;
  if not public.valid_img(p_img) then perform public.bad('Upload the refund proof picture first (JPG, PNG or WebP, under 1 MB).'); end if;
  select * into o from public.orders where id = p_id for update;
  if not found then perform public.bad('Order not found'); end if;
  if not (o.data ? 'paidAt') then perform public.bad('Only an order that was paid can be refunded.'); end if;
  if o.data ? 'refund' then perform public.bad('This order is already marked as refunded.'); end if;
  tot := coalesce((o.data ->> 'total')::numeric, 0);
  amt := round(coalesce(p_amount, tot), 2);
  if amt <= 0 or amt > tot then perform public.bad('The refund must be more than 0 and no more than the order total.'); end if;
  ms := coalesce(o.data -> 'msgs', '[]'::jsonb);
  if jsonb_typeof(p_msgs) = 'array' then
    for m in select * from jsonb_array_elements(p_msgs) loop
      if m ->> 'channel' in ('whatsapp', 'email') and btrim(coalesce(m ->> 'text', '')) <> '' then
        ms := ms || jsonb_build_array(jsonb_build_object('at', t, 'channel', m ->> 'channel', 'status', 'refunded', 'text', left(m ->> 'text', 800), 'by', 'staff'));
      end if;
    end loop;
  end if;
  insert into public.order_files (order_id, kind, idx, data, at) values (p_id, 'refund', 0, p_img, t)
    on conflict (order_id, kind, idx) do update set data = excluded.data, at = excluded.at;
  d := o.data || jsonb_build_object('msgs', ms, 'refund', jsonb_build_object(
         'amount', amt, 'full', amt >= tot, 'at', t, 'note', left(btrim(coalesce(p_note, '')), 200), 'proof', true,
         'by', coalesce(nullif(me.name, ''), me.username, me.email)));
  perform set_config('dd.op', 'order', true);
  update public.orders set data = d, updated_at = t where id = p_id;
  perform public.log_act('Order ' || coalesce(d ->> 'code', p_id), 'refunded ' || amt::text || case when amt >= tot then ' (full)' else ' (part)' end || ' with proof picture');
  return d;
end $$;
revoke all on function public.admin_refund_order(text, numeric, text, jsonb, text) from public, anon, authenticated;
grant execute on function public.admin_refund_order(text, numeric, text, jsonb, text) to authenticated;

create or replace function public.admin_order_files(p_id text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.assert_admin();
  if not (public.has_perm('orders') or public.has_perm('complaints')) then
    raise exception 'You don''t have access to orders. Ask the owner.' using errcode = '42501'; end if;
  return jsonb_build_object(
    'proof', (select data from public.order_files where order_id = p_id and kind = 'proof' and idx = 0),
    'photos', coalesce((select jsonb_agg(data order by idx) from public.order_files where order_id = p_id and kind = 'complaint'), '[]'::jsonb),
    'place', (select data from public.order_files where order_id = p_id and kind = 'place' and idx = 0),
    'refund', (select data from public.order_files where order_id = p_id and kind = 'refund' and idx = 0));
end $$;
revoke all on function public.admin_order_files(text) from public;
grant execute on function public.admin_order_files(text) to authenticated;


-- ===== 20260125000000_gift_rules.sql =====
-- Callebrownies migration 25: gift rules per box size, drawn when the payment proof is sent.
--  * a gifts promo now has a pool (sale.gifts: id, name, img, stock - blank = unlimited) and rules (sale.rules: from, to, limit, mode specific|random, ids)
--  * the gifts are chosen when the customer sends the payment proof (submit_proof), once per order; random picks can't be rerolled
--  * the gift only counts once the owner confirms the payment (labels already need a paid order)
--  * stock is reserved when a gift is drawn and given back if the order is cancelled
-- Safe to run more than once. Run after migration 24. Old-format gift promos (no rules) simply stop giving gifts; make a new one.

create table if not exists public.gift_use (
  promo text not null, gift text not null, used int not null default 0,
  primary key (promo, gift)
);
alter table public.gift_use enable row level security;     -- no policies: only the server functions touch it

create or replace function public.gift_rule(p_rules jsonb, p_n int) returns jsonb
language sql immutable set search_path = public as $$
  select r from jsonb_array_elements(coalesce(p_rules, '[]'::jsonb)) r
  where coalesce(nullif(r ->> 'from', '')::int, 0) <= p_n and p_n <= coalesce(nullif(r ->> 'to', '')::int, 0) limit 1
$$;

-- gives reserved stock back
create or replace function public.gift_release(p_gifts jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare g jsonb;
begin
  for g in select value from jsonb_array_elements(case when jsonb_typeof(p_gifts) = 'array' then p_gifts else '[]'::jsonb end) loop
    continue when not coalesce((g ->> 'reserved')::boolean, false);
    update public.gift_use set used = greatest(0, used - 1) where promo = g ->> 'promoId' and gift = g ->> 'id';
  end loop;
end $$;

-- the gifts a box of p_n brownies earns for this order. Specific rules give the ticked gifts, random rules pick
-- (limit) of the ticked gifts in an order only the server can work out, so refreshing or changing things can't reroll.
create or replace function public.draw_gifts(p_id text, p_n int, p_at bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare s record; r jsonb; g jsonb; res jsonb := '[]'::jsonb; sec text; lim int; md text; ids jsonb; cnt int; resv boolean;
begin
  sec := coalesce((select data ->> 'v' from public.private_kv where key = 'quote_secret'), '');
  for s in select c.id, c.data from public.coll c
           where c.coll = 'sales' and c.data ->> 'type' = 'gifts'
             and (c.data ->> 'start')::bigint <= p_at and p_at < (c.data ->> 'end')::bigint
           order by c.id loop
    r := public.gift_rule(s.data -> 'rules', p_n);
    continue when r is null;
    lim := greatest(1, least(5, coalesce(nullif(r ->> 'limit', '')::numeric, 1)::int));
    md := case when r ->> 'mode' = 'random' then 'random' else 'specific' end;
    ids := coalesce(r -> 'ids', '[]'::jsonb);
    cnt := 0;
    for g in
      select e.value from jsonb_array_elements(coalesce(s.data -> 'gifts', '[]'::jsonb)) with ordinality as e(value, ord)
      where btrim(coalesce(e.value ->> 'name', '')) <> '' and ids @> to_jsonb(e.value ->> 'id')
        and (coalesce(e.value ->> 'stock', '') = ''
             or coalesce((select u.used from public.gift_use u where u.promo = s.id and u.gift = e.value ->> 'id'), 0) < (e.value ->> 'stock')::numeric)
      order by case when md = 'random' then md5(sec || p_id || s.id || coalesce(r ->> 'id', '') || (e.value ->> 'id')) else lpad(e.ord::text, 6, '0') end
    loop
      exit when cnt >= lim;
      resv := false;
      if coalesce(g ->> 'stock', '') <> '' then
        insert into public.gift_use (promo, gift, used) values (s.id, g ->> 'id', 0) on conflict do nothing;
        update public.gift_use set used = used + 1 where promo = s.id and gift = g ->> 'id' and used < (g ->> 'stock')::numeric;
        continue when not found;
        resv := true;
      end if;
      res := res || jsonb_build_array(jsonb_build_object('id', g ->> 'id', 'name', left(g ->> 'name', 40), 'promo', s.data ->> 'name',
                                                         'promoId', s.id, 'random', md = 'random', 'reserved', resv));
      cnt := cnt + 1;
    end loop;
  end loop;
  return res;
end $$;
revoke all on function public.gift_rule(jsonb, int), public.gift_release(jsonb), public.draw_gifts(text, int, bigint) from public, anon, authenticated;

-- a cancelled order gives its reserved gifts back (and loses them; a reopened order is drawn again when its proof is sent)
create or replace function public.orders_gift_release() returns trigger
language plpgsql set search_path = public as $$
begin
  if (new.data ->> 'status') = 'cancelled' and (old.data ->> 'status') is distinct from 'cancelled' and new.data ? 'giftsAt' then
    perform public.gift_release(new.data -> 'gifts');
    new.data := (new.data - 'giftsAt') || jsonb_build_object('gifts', '[]'::jsonb);
  end if;
  return new;
end $$;
revoke all on function public.orders_gift_release() from public, anon, authenticated;
create or replace trigger orders_gift_release_trg before update on public.orders
  for each row execute function public.orders_gift_release();

-- the customer sends the payment proof: the gifts are drawn now (once per order)
create or replace function public.submit_proof(p_id text, p_token text, p_name text, p_img text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders; t bigint := public.now_ms(); nm text := btrim(coalesce(p_name, '')); ms jsonb := '[]'::jsonb; ch text; msg text; d jsonb;
begin
  if not public.owns(p_id, p_token) then perform public.bad('We couldn''t find that order.'); end if;
  if length(nm) < 2 or length(nm) > 80 then perform public.bad('Please enter the name on the payment.'); end if;
  if not public.valid_img(p_img) then perform public.bad('Please attach a photo or screenshot (JPG, PNG or WebP, under 1 MB).'); end if;
  if not public.throttle_ok('proof:' || p_id, 8, 3600000) then perform public.bad('Too many tries. Please wait a while.'); end if;
  select * into o from public.orders where id = p_id for update;
  if o.status <> 'awaiting' then perform public.bad('This order is no longer waiting for payment.'); end if;
  insert into public.order_files (order_id, kind, idx, data, at) values (p_id, 'proof', 0, p_img, t)
    on conflict (order_id, kind, idx) do update set data = excluded.data, at = excluded.at;
  msg := 'Hi ' || coalesce(nullif(split_part(o.data #>> '{customer,name}', ' ', 1), ''), 'there') || ', we got your payment proof for order ' || (o.data ->> 'code') || ' and we''re checking it now.';
  for ch in select unnest(case coalesce(o.data ->> 'notify', 'both') when 'both' then array['whatsapp','email'] when 'none' then array[]::text[] else array[o.data ->> 'notify'] end) loop
    ms := ms || jsonb_build_array(jsonb_build_object('at', t, 'channel', ch, 'status', 'review', 'text', msg, 'by', 'system'));
  end loop;
  d := (o.data - 'rejected') || jsonb_build_object('status', 'review', 'proof', jsonb_build_object('name', nm, 'at', t, 'img', ''),
         'msgs', coalesce(o.data -> 'msgs', '[]'::jsonb) || ms);
  if not (o.data ? 'giftsAt') then
    d := d || jsonb_build_object('gifts', public.draw_gifts(p_id, coalesce((o.data ->> 'size')::int, 0), t), 'giftsAt', t);
  end if;
  update public.orders set data = d where id = p_id;
  return d;
end $$;

-- the owner's gift stock counter (used so far per promo and gift)
create or replace function public.admin_gift_used() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.assert_admin();
  return coalesce((select jsonb_object_agg(promo, m) from (select promo, jsonb_object_agg(gift, used) m from public.gift_use group by promo) x), '{}'::jsonb);
end $$;
revoke all on function public.admin_gift_used() from public, anon;
grant execute on function public.admin_gift_used() to authenticated;

-- place_order: no gifts at checkout any more (they are drawn when the proof is sent). Editing an order keeps its draw while the box size stays the same.
do $$
declare d text; d0 text;
begin
  d0 := pg_get_functiondef('public.place_order(jsonb)'::regprocedure); d := d0;
  d := regexp_replace(d, 'if edit_id is not null and eo\.data \? ''gifts''.*?end if;',
    'if edit_id is not null and coalesce((eo.data ->> ''size'')::int, -1) = v_size then gifts := coalesce(eo.data -> ''gifts'', ''[]''::jsonb); else gifts := ''[]''::jsonb; end if;', 's');
  d := regexp_replace(d, 'update public\.orders set data = od where id = edit_id;',
    'if jsonb_array_length(gifts) = 0 and (eo.data ? ''giftsAt'') then perform public.gift_release(eo.data -> ''gifts''); od := od - ''giftsAt''; end if; update public.orders set data = od where id = edit_id;');
  if d = d0 then raise exception 'place_order patch did not apply'; end if;
  if position('giftsAt' in d) = 0 then raise exception 'place_order edit patch did not apply'; end if;
  if position('gifts_for' in d) > 0 then raise exception 'place_order still draws gifts at checkout'; end if;
  execute d;
end $$;


-- ===== 20260126000000_bell_messages_reject_first.sql =====
-- Callebrownies migration 26:
--  * a customer message can use the channel 'bell' (the shop's bell only, no WhatsApp or email): staff who choose
--    "bell only" when changing a status still notify the customer in the shop
--  * an order with a payment proof can only go back to Awaiting payment by rejecting the proof (with a reason)
-- Safe to run more than once. Run after migration 25.
do $$
declare d text; d0 text; e text; e0 text;
begin
  d0 := pg_get_functiondef('public.admin_patch_order_core(text,jsonb)'::regprocedure); d := d0;
  d := replace(d, $q$(m ->> 'channel') in ('whatsapp','email')$q$, $q$(m ->> 'channel') in ('whatsapp','email','bell')$q$);
  if d = d0 and position($q$'whatsapp','email','bell'$q$ in d0) = 0 then raise exception 'core patch did not apply'; end if;
  execute d;
  e0 := pg_get_functiondef('public.admin_patch_order(text,jsonb)'::regprocedure); e := e0;
  if position('Reject the payment proof first' in e0) = 0 then
    e := regexp_replace(e, $q$(if cur = 'new' and st = 'awaiting' then\s+perform public\.bad\('[^']*'\); end if;)$q$,
      $q$\1
    if cur = 'review' and st = 'awaiting' and not (pt ? 'rejected') then
      perform public.bad('Reject the payment proof first. An order with a payment proof only goes back to Awaiting payment by rejecting the proof (with a reason).'); end if;$q$, 'n');
    if e = e0 then raise exception 'status rule patch did not apply'; end if;
    execute e;
  end if;
end $$;


-- ===== 20260127000000_courier_private.sql =====
-- Callebrownies migration 27: the courier's live tracking link stays private (only the team can see it).
-- Courier tracking pages can show a map with the pickup point, so customers never receive the link
-- unless the owner switches "Show the live tracking link to customers" on in Delivery & courier.
-- Safe to run more than once. Run after migration 26.
create table if not exists public.courier_private (
  order_id    text primary key references public.orders(id) on delete cascade,
  link        text not null default '',
  tracking_id text not null default '',
  at          bigint
);
alter table public.courier_private enable row level security;      -- no policies: only the server functions touch it

-- links already saved inside orders move here, and are removed from what customers can load
insert into public.courier_private (order_id, link, tracking_id, at)
  select id, coalesce(data #>> '{bship,link}', ''), coalesce(data #>> '{bship,trackingId}', ''), public.now_ms()
  from public.orders where data #>> '{bship,link}' is not null or data #>> '{bship,trackingId}' is not null
  on conflict (order_id) do update set link = excluded.link, tracking_id = excluded.tracking_id;
update public.orders set data = jsonb_set(data, '{bship}', (data -> 'bship') - 'link' - 'trackingId')
  where data #>> '{bship,link}' is not null or data #>> '{bship,trackingId}' is not null;

-- the team reads the link with the order's pictures
create or replace function public.admin_order_files(p_id text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.assert_admin();
  if not (public.has_perm('orders') or public.has_perm('complaints')) then
    raise exception 'You don''t have access to orders. Ask the owner.' using errcode = '42501'; end if;
  return jsonb_build_object(
    'proof', (select data from public.order_files where order_id = p_id and kind = 'proof' and idx = 0),
    'photos', coalesce((select jsonb_agg(data order by idx) from public.order_files where order_id = p_id and kind = 'complaint'), '[]'::jsonb),
    'place', (select data from public.order_files where order_id = p_id and kind = 'place' and idx = 0),
    'refund', (select data from public.order_files where order_id = p_id and kind = 'refund' and idx = 0),
    'courier', (select jsonb_build_object('link', link, 'trackingId', tracking_id) from public.courier_private where order_id = p_id));
end $$;
revoke all on function public.admin_order_files(text) from public;
grant execute on function public.admin_order_files(text) to authenticated;


-- ===== 20260128000000_abuse_limits.sql =====
-- Callebrownies migration 28: abuse protection.
--  * limits per visitor (by the connection's IP address) on placing orders, tracking, coupon tries and visit logging,
--    on top of the old shop-wide limits (one visitor can no longer use up everyone's allowance, and can't place unlimited orders)
--  * a small cache for courier price and address lookups, so repeated requests don't cost Biteship / Google calls
-- Safe to run more than once. Run after migration 27.

-- the caller's IP address as seen by the API gateway (Cloudflare's header can't be faked by the visitor)
create or replace function public.client_ip() returns text
language plpgsql stable set search_path = public as $$
declare h jsonb;
begin
  begin h := nullif(current_setting('request.headers', true), '')::jsonb; exception when others then h := null; end;
  return coalesce(nullif(btrim(split_part(coalesce(h ->> 'cf-connecting-ip', h ->> 'x-forwarded-for', ''), ',', 1)), ''), 'unknown');
end $$;

-- the same kind of limit as throttle_ok, but counted per IP address (no limit when the address is unknown)
create or replace function public.throttle_ip(p_key text, p_max int, p_window_ms bigint) returns boolean
language plpgsql security definer set search_path = public as $$
declare ip text := public.client_ip();
begin
  if ip = 'unknown' then return true; end if;
  return public.throttle_ok(p_key || ':' || ip, p_max, p_window_ms);
end $$;
revoke all on function public.client_ip(), public.throttle_ip(text, int, bigint) from public, anon, authenticated;

create table if not exists public.quote_cache (
  k   text primary key,
  exp bigint not null,
  data jsonb not null
);
alter table public.quote_cache enable row level security;      -- only the server functions use it

do $$
declare
  rows text[][] := array[
    array['place_order',  'order', 'if not public.throttle_ip(''order-h'', 10, 3600000) or not public.throttle_ip(''order-d'', 30, 86400000) then perform public.bad(''Too many orders from this connection. Please try again later.''); end if;'],
    array['track_order',  'track', 'if not public.throttle_ip(''track-m'', 12, 60000) or not public.throttle_ip(''track-h'', 120, 3600000) then perform public.bad(''Too many tries. Please wait a minute.''); end if;'],
    array['check_coupon', 'cp',    'if not public.throttle_ip(''cp-m'', 20, 60000) then return jsonb_build_object(''ok'', false, ''err'', ''Too many tries. Please wait a moment.''); end if;'],
    array['log_visit',    'visit', 'if not public.throttle_ip(''visit-m'', 120, 60000) then return; end if;']];
  i int; d text; n text;
begin
  for i in 1 .. 4 loop
    select pg_get_functiondef(p.oid) into d from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = rows[i][1] limit 1;
    if d is null or position(rows[i][3] in d) > 0 then continue; end if;      -- missing, or already patched
    n := regexp_replace(d, '(if not public\.throttle_ok\(''' || rows[i][2] || ''', \d+, 60000\) then .*?end if;)', '\1 ' || replace(rows[i][3], '\', '\\'), 's');
    if n <> d then execute n; end if;
  end loop;
end $$;


-- ===== 20260129000000_security_tab.sql =====
-- Callebrownies migration 29: Security tab (owner only).
--  * every abuse limit and daily courier cap can be changed by the owner (stored privately in private_kv 'security';
--    a missing value uses the built-in default, 0 turns that limit off)
--  * fixes migration 28: the per-visitor checks now sit right after the shop-wide checks
--    (before, the per-visitor order limit only ran when an order code collided, and visits were counted after saving)
--  * changing the limits needs Owner mode (owner password, 5 minutes)
-- Safe to run more than once. Run after migration 28.

create or replace function public.sec_lim(p_name text, p_dflt int) returns int
language sql stable security definer set search_path = public as $$
  select coalesce((select case when (data ->> p_name) ~ '^\d{1,7}$' then (data ->> p_name)::int end
                   from public.private_kv where key = 'security'), p_dflt)
$$;
create or replace function public.lim_ok(p_key text, p_name text, p_dflt int, p_window_ms bigint) returns boolean
language plpgsql security definer set search_path = public as $$
declare m int := public.sec_lim(p_name, p_dflt);
begin return m <= 0 or public.throttle_ok(p_key, m, p_window_ms); end $$;
create or replace function public.lim_ip(p_key text, p_name text, p_dflt int, p_window_ms bigint) returns boolean
language plpgsql security definer set search_path = public as $$
declare m int := public.sec_lim(p_name, p_dflt);
begin return m <= 0 or public.throttle_ip(p_key, m, p_window_ms); end $$;
revoke all on function public.sec_lim(text, int), public.lim_ok(text, text, int, bigint), public.lim_ip(text, text, int, bigint) from public, anon, authenticated;

-- rewrite the limit checks in the live functions (exact text swaps; already-swapped text is left alone)
do $$
declare
  r text[][] := array[
    -- function, old text, new text
    ['place_order', ' if not public.throttle_ip(''order-h'', 10, 3600000) or not public.throttle_ip(''order-d'', 30, 86400000) then perform public.bad(''Too many orders from this connection. Please try again later.''); end if;', ''],
    ['place_order', 'if not public.throttle_ok(''order'', 60, 60000) then perform public.bad(''We''''re very busy right now. Please try again in a minute.''); end if;',
                    'if not public.lim_ok(''order'', ''orderAll'', 60, 60000) then perform public.bad(''We''''re very busy right now. Please try again in a minute.''); end if;
    if not public.lim_ip(''order-h'', ''orderIpH'', 10, 3600000) or not public.lim_ip(''order-d'', ''orderIpD'', 30, 86400000) then perform public.bad(''Too many orders from this connection. Please try again later.''); end if;'],
    ['place_order', 'if open_n >= 3 then perform public.bad(''You already have 3 unpaid orders. Please pay or cancel one first.''); end if;',
                    'if public.sec_lim(''phoneOpen'', 3) > 0 and open_n >= public.sec_lim(''phoneOpen'', 3) then perform public.bad(''You already have '' || open_n || '' unpaid orders. Please pay or cancel one first.''); end if;'],
    ['track_order', ' if not public.throttle_ip(''track-m'', 12, 60000) or not public.throttle_ip(''track-h'', 120, 3600000) then perform public.bad(''Too many tries. Please wait a minute.''); end if;', ''],
    ['track_order', 'if not public.throttle_ok(''track'', 30, 60000) then perform public.bad(''Too many tries. Please wait a minute.''); end if;',
                    'if not public.lim_ok(''track'', ''trackAll'', 30, 60000) then perform public.bad(''Too many tries. Please wait a minute.''); end if;
  if not public.lim_ip(''track-m'', ''trackIpM'', 12, 60000) or not public.lim_ip(''track-h'', ''trackIpH'', 120, 3600000) then perform public.bad(''Too many tries. Please wait a minute.''); end if;'],
    ['check_coupon', ' if not public.throttle_ip(''cp-m'', 20, 60000) then return jsonb_build_object(''ok'', false, ''err'', ''Too many tries. Please wait a moment.''); end if;', ''],
    ['check_coupon', 'if not public.throttle_ok(''cp'', 120, 60000) then return jsonb_build_object(''ok'', false, ''err'', ''Too many tries. Please wait a moment.''); end if;',
                     'if not public.lim_ok(''cp'', ''cpAll'', 120, 60000) or not public.lim_ip(''cp-m'', ''cpIpM'', 20, 60000) then return jsonb_build_object(''ok'', false, ''err'', ''Too many tries. Please wait a moment.''); end if;'],
    ['log_visit', ' if not public.throttle_ip(''visit-m'', 120, 60000) then return; end if;', ''],
    ['log_visit', 'if not public.throttle_ok(''visit'', 600, 60000) then return; end if;',
                  'if not public.lim_ok(''visit'', ''visitAll'', 600, 60000) or not public.lim_ip(''visit-m'', ''visitIpM'', 120, 60000) then return; end if;'],
    ['submit_proof', 'public.throttle_ok(''proof:'' || p_id, 8, 3600000)', 'public.lim_ok(''proof:'' || p_id, ''proofH'', 8, 3600000)'],
    ['submit_complaint', 'public.throttle_ok(''complaint:'' || p_id, 4, 3600000)', 'public.lim_ok(''complaint:'' || p_id, ''complaintH'', 4, 3600000)'],
    ['submit_place', 'public.throttle_ok(''place:'' || p_id, 12, 3600000)', 'public.lim_ok(''place:'' || p_id, ''placeH'', 12, 3600000)']];
  i int; f text; d text; n text;
begin
  for f in select distinct x from unnest(array['place_order','track_order','check_coupon','log_visit','submit_proof','submit_complaint','submit_place']) x loop
    select pg_get_functiondef(p.oid) into d from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = f limit 1;
    if d is null then continue; end if;
    n := d;
    for i in 1 .. array_length(r, 1) loop
      if r[i][1] = f then n := replace(n, r[i][2], r[i][3]); end if;
    end loop;
    if n <> d then execute n; end if;
  end loop;
end $$;

-- owner: read the limits, Owner mode state and how much of each daily courier cap was used in the last 24 hours
create or replace function public.admin_security_get() returns jsonb
language plpgsql security definer set search_path = public as $$
declare me public.admins := public.team_me(); em text := lower(coalesce(auth.jwt() ->> 'email', '')); t bigint := public.now_ms();
begin
  perform public.assert_admin();
  if me.role is distinct from 'owner' then perform public.bad('Only an owner can see Security.'); end if;
  return jsonb_build_object(
    'cfg', coalesce((select data from public.private_kv where key = 'security'), '{}'::jsonb),
    'until', coalesce((select until from public.order_unlock where order_id = '__security__' and email = em and until > t), 0),
    'used', jsonb_build_object(
      'rates',   (select count(*) from public.throttle where k = 'bs-day-rates'   and at > t - 86400000),
      'geocode', (select count(*) from public.throttle where k = 'bs-day-geocode' and at > t - 86400000),
      'areas',   (select count(*) from public.throttle where k = 'bs-day-areas'   and at > t - 86400000),
      'orders',  (select count(*) from public.orders where created_at > t - 86400000)));
end $$;

-- owner: Owner mode for the Security tab (5 minutes); empty password = turn it off
create or replace function public.admin_security_mode(p_password text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me public.admins := public.team_me(); em text := lower(coalesce(auth.jwt() ->> 'email', '')); u bigint := public.now_ms() + 300000;
begin
  perform public.assert_admin();
  if me.role is distinct from 'owner' then perform public.bad('Only an owner can use Owner mode.'); end if;
  if coalesce(p_password, '') = '' then
    update public.order_unlock set until = 0 where order_id = '__security__' and email = em;
    return jsonb_build_object('ok', true, 'until', 0);
  end if;
  if not public.throttle_ok('sudo:' || em, 8, 600000) then
    return jsonb_build_object('ok', false, 'err', 'Too many tries. Please wait 10 minutes.'); end if;
  if not public.owner_pw_ok(p_password) then
    perform public.log_act('Owner password wrong', 'Owner mode on Security');
    return jsonb_build_object('ok', false, 'err', 'That owner password isn''t right.'); end if;
  insert into public.order_unlock (order_id, email, until) values ('__security__', em, u)
    on conflict (order_id, email) do update set until = excluded.until;
  perform public.log_act('Owner mode on: Security', 'for 5 minutes');
  return jsonb_build_object('ok', true, 'until', u);
end $$;

-- owner (Owner mode on): save the limits. Unknown names are dropped; numbers are whole, 0 to 1,000,000 (0 = no limit)
create or replace function public.admin_security_set(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me public.admins := public.team_me(); out jsonb := '{}'::jsonb; k text; v text;
  names text[] := array['orderAll','orderIpH','orderIpD','phoneOpen','trackAll','trackIpM','trackIpH','cpAll','cpIpM','visitAll','visitIpM',
                        'proofH','complaintH','placeH','bsAreasIpM','bsGeoIpM','bsGeoIpH','bsRatesIpM','bsRatesIpH','capRates','capGeo','capAreas','cacheMin'];
begin
  perform public.assert_admin();
  if me.role is distinct from 'owner' then perform public.bad('Only an owner can change Security.'); end if;
  if not public.owner_unlocked('__security__') then perform public.bad('Turn on Owner mode first (owner password).'); end if;
  foreach k in array names loop
    v := btrim(coalesce(p ->> k, ''));
    if v = '' then continue; end if;
    if v !~ '^\d{1,7}$' or v::int > 1000000 then perform public.bad('"' || k || '" must be a whole number from 0 to 1,000,000.'); end if;
    out := out || jsonb_build_object(k, v::int);
  end loop;
  if coalesce((p ->> 'courierOff')::boolean, false) then out := out || '{"courierOff":true}'::jsonb; end if;
  insert into public.private_kv (key, data, updated_at) values ('security', out, public.now_ms())
    on conflict (key) do update set data = excluded.data, updated_at = excluded.updated_at;
  perform public.log_act('Security limits changed', case when out ? 'courierOff' then 'courier prices paused' else 'saved' end);
  return out;
end $$;

revoke all on function public.admin_security_get(), public.admin_security_mode(text), public.admin_security_set(jsonb) from public, anon, authenticated;
grant execute on function public.admin_security_get(), public.admin_security_mode(text), public.admin_security_set(jsonb) to authenticated;


-- ===== 20260130000000_limit_warnings.sql =====
-- Callebrownies migration 30: early warnings, owner alerts and resetting the limits (Security tab).
--  * a visitor who has used most of their allowance (default 70%, Security tab "warnPct") gets a friendly warning:
--    place_order / track_order / check_coupon answers carry "_warn" (the shop shows the warning pop-up)
--  * owner alerts: a whole-shop limit was reached, or a daily courier cap passed 70% / was reached (Security tab + badge)
--  * the owner can reset the counters (all, or one limit) with Owner mode on
--  * per-visitor daily courier limits are handled by the biteship function (throttle_n)
-- Safe to run more than once. Run after migration 29.

-- owner alerts (newest first, at most 30); p_every_ms: the same alert at most once in that time
create or replace function public.sec_alert(p_name text, p_lvl int, p_every_ms bigint) returns void
language plpgsql security definer set search_path = public as $$
declare a jsonb; s jsonb;
begin
  if not public.throttle_ok('alert:' || p_name || ':' || p_lvl, 1, p_every_ms) then return; end if;
  select data -> 'list', data -> 'seen' into a, s from public.private_kv where key = 'sec_alerts';
  a := jsonb_build_array(jsonb_build_object('at', public.now_ms(), 'k', p_name, 'lvl', p_lvl)) || coalesce(a, '[]'::jsonb);
  a := (select coalesce(jsonb_agg(x order by i), '[]'::jsonb) from jsonb_array_elements(a) with ordinality t(x, i) where i <= 30);
  insert into public.private_kv (key, data, updated_at) values ('sec_alerts', jsonb_build_object('list', a, 'seen', coalesce(s, '0'::jsonb)), public.now_ms())
    on conflict (key) do update set data = excluded.data, updated_at = excluded.updated_at;
end $$;

-- a limit for the whole shop; when it is reached the owner is told (at most once an hour)
create or replace function public.lim_ok(p_key text, p_name text, p_dflt int, p_window_ms bigint) returns boolean
language plpgsql security definer set search_path = public as $$
declare m int := public.sec_lim(p_name, p_dflt);
begin
  if m <= 0 or public.throttle_ok(p_key, m, p_window_ms) then return true; end if;
  if p_name in ('orderAll', 'trackAll', 'cpAll', 'visitAll') then perform public.sec_alert(p_name, 100, 3600000); end if;
  return false;
end $$;

-- a limit per visitor; past the warning point the answer is marked so the shop can show the friendly warning
create or replace function public.lim_ip(p_key text, p_name text, p_dflt int, p_window_ms bigint) returns boolean
language plpgsql security definer set search_path = public as $$
declare m int := public.sec_lim(p_name, p_dflt); ip text; v_k text; n int; t bigint := public.now_ms(); w int;
begin
  if m <= 0 then return true; end if;
  ip := public.client_ip();
  if ip = 'unknown' then return true; end if;
  v_k := p_key || ':' || ip;
  select count(*) into n from public.throttle where throttle.k = v_k and throttle.at > t - p_window_ms;
  if n >= m then return false; end if;
  insert into public.throttle values (v_k, t);
  w := public.sec_lim('warnPct', 70);
  if w > 0 and w < 100 and n + 1 >= ceil(m * w / 100.0) then perform set_config('dd.warn', p_name, true); end if;
  return true;
end $$;

-- adds the warning mark to an answer
create or replace function public.with_warn(j jsonb) returns jsonb
language sql stable set search_path = public as $$
  select case when coalesce(current_setting('dd.warn', true), '') <> '' and jsonb_typeof(j) = 'object'
              then j || jsonb_build_object('_warn', current_setting('dd.warn', true)) else j end
$$;

-- for the courier function: like throttle_ok, but returns how many were used (with this one), or -1 when the limit is reached
create or replace function public.throttle_n(p_key text, p_max int, p_window_ms bigint) returns int
language plpgsql security definer set search_path = public as $$
declare n int; t bigint := public.now_ms();
begin
  select count(*) into n from public.throttle where k = p_key and at > t - p_window_ms;
  if n >= p_max then return -1; end if;
  insert into public.throttle values (p_key, t);
  return n + 1;
end $$;

revoke all on function public.sec_alert(text, int, bigint), public.lim_ok(text, text, int, bigint), public.lim_ip(text, text, int, bigint),
  public.with_warn(jsonb), public.throttle_n(text, int, bigint) from public, anon, authenticated;
grant execute on function public.sec_alert(text, int, bigint), public.throttle_n(text, int, bigint) to service_role;

-- the shop's answers carry the warning mark
do $$
declare
  r text[][] := array[
    ['place_order',  'return jsonb_build_object(''order'', od, ''token'', tok);', 'return public.with_warn(jsonb_build_object(''order'', od, ''token'', tok));'],
    ['track_order',  'return jsonb_build_object(''found'', false);', 'return public.with_warn(jsonb_build_object(''found'', false));'],
    ['track_order',  'return jsonb_build_object(''found'', true, ''order'', o.data, ''token'', tok);', 'return public.with_warn(jsonb_build_object(''found'', true, ''order'', o.data, ''token'', tok));'],
    ['check_coupon', 'return r;', 'return public.with_warn(r);']];
  i int; f text; d text; n text;
begin
  for f in select unnest(array['place_order','track_order','check_coupon']) loop
    select pg_get_functiondef(p.oid) into d from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = f limit 1;
    if d is null then continue; end if;
    n := d;
    for i in 1 .. array_length(r, 1) loop
      if r[i][1] = f and position(r[i][3] in n) = 0 then n := replace(n, r[i][2], r[i][3]); end if;
    end loop;
    if n <> d then execute n; end if;
  end loop;
end $$;

-- owner: the limits, Owner mode, usage of the daily caps (last 24 hours) and the alerts
create or replace function public.admin_security_get() returns jsonb
language plpgsql security definer set search_path = public as $$
declare me public.admins := public.team_me(); em text := lower(coalesce(auth.jwt() ->> 'email', '')); t bigint := public.now_ms(); al jsonb;
begin
  perform public.assert_admin();
  if me.role is distinct from 'owner' then perform public.bad('Only an owner can see Security.'); end if;
  select data into al from public.private_kv where key = 'sec_alerts';
  return jsonb_build_object(
    'cfg', coalesce((select data from public.private_kv where key = 'security'), '{}'::jsonb),
    'until', coalesce((select until from public.order_unlock where order_id = '__security__' and email = em and until > t), 0),
    'alerts', coalesce(al -> 'list', '[]'::jsonb), 'seen', coalesce(al -> 'seen', '0'::jsonb),
    'used', jsonb_build_object(
      'rates',   (select count(*) from public.throttle where k = 'bs-day-rates'   and at > t - 86400000),
      'geocode', (select count(*) from public.throttle where k = 'bs-day-geocode' and at > t - 86400000),
      'areas',   (select count(*) from public.throttle where k = 'bs-day-areas'   and at > t - 86400000),
      'orders',  (select count(*) from public.orders where created_at > t - 86400000)));
end $$;

-- owner: how many alerts are new, and the newest one (checked every minute by the team site)
create or replace function public.admin_security_alerts() returns jsonb
language plpgsql security definer set search_path = public as $$
declare me public.admins := public.team_me(); al jsonb; s bigint;
begin
  perform public.assert_admin();
  if me.role is distinct from 'owner' then return jsonb_build_object('n', 0); end if;
  select data into al from public.private_kv where key = 'sec_alerts';
  s := coalesce((al ->> 'seen')::bigint, 0);
  return jsonb_build_object('n', (select count(*) from jsonb_array_elements(coalesce(al -> 'list', '[]'::jsonb)) x where (x ->> 'at')::bigint > s),
                            'last', coalesce(al -> 'list' -> 0, 'null'::jsonb));
end $$;

-- owner: mark the alerts as seen
create or replace function public.admin_security_seen() returns void
language plpgsql security definer set search_path = public as $$
declare me public.admins := public.team_me();
begin
  perform public.assert_admin();
  if me.role is distinct from 'owner' then return; end if;
  update public.private_kv set data = jsonb_set(data, '{seen}', to_jsonb(public.now_ms())) where key = 'sec_alerts';
end $$;

-- owner (Owner mode on): save the limits
create or replace function public.admin_security_set(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me public.admins := public.team_me(); out jsonb := '{}'::jsonb; k text; v text;
  names text[] := array['orderAll','orderIpH','orderIpD','phoneOpen','trackAll','trackIpM','trackIpH','cpAll','cpIpM','visitAll','visitIpM',
                        'proofH','complaintH','placeH','bsAreasIpM','bsAreasIpD','bsGeoIpM','bsGeoIpH','bsGeoIpD','bsRatesIpM','bsRatesIpH','bsRatesIpD',
                        'capRates','capGeo','capAreas','cacheMin','warnPct','alertPct'];
begin
  perform public.assert_admin();
  if me.role is distinct from 'owner' then perform public.bad('Only an owner can change Security.'); end if;
  if not public.owner_unlocked('__security__') then perform public.bad('Turn on Owner mode first (owner password).'); end if;
  foreach k in array names loop
    v := btrim(coalesce(p ->> k, ''));
    if v = '' then continue; end if;
    if v !~ '^\d{1,7}$' or v::int > 1000000 then perform public.bad('"' || k || '" must be a whole number from 0 to 1,000,000.'); end if;
    if k in ('warnPct', 'alertPct') and v::int > 99 then perform public.bad('Warning points must be from 0 to 99 (%).'); end if;
    out := out || jsonb_build_object(k, v::int);
  end loop;
  if coalesce((p ->> 'courierOff')::boolean, false) then out := out || '{"courierOff":true}'::jsonb; end if;
  insert into public.private_kv (key, data, updated_at) values ('security', out, public.now_ms())
    on conflict (key) do update set data = excluded.data, updated_at = excluded.updated_at;
  perform public.log_act('Security limits changed', case when out ? 'courierOff' then 'courier prices paused' else 'saved' end);
  return out;
end $$;

-- owner (Owner mode on): start counting again from zero, for one limit or for everything (the owner-password lockout is kept)
create or replace function public.admin_security_reset(p_name text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me public.admins := public.team_me(); pat text; n int;
  m jsonb := '{"orderAll":"order","orderIpH":"order-h:%","orderIpD":"order-d:%","trackAll":"track","trackIpM":"track-m:%","trackIpH":"track-h:%",
    "cpAll":"cp","cpIpM":"cp-m:%","visitAll":"visit","visitIpM":"visit-m:%","proofH":"proof:%","complaintH":"complaint:%","placeH":"place:%",
    "bsAreasIpM":"bs-areas:%","bsAreasIpD":"bs-areas-d:%","bsGeoIpM":"bs-geo-m:%","bsGeoIpH":"bs-geo-h:%","bsGeoIpD":"bs-geo-d:%",
    "bsRatesIpM":"bs-rates-m:%","bsRatesIpH":"bs-rates-h:%","bsRatesIpD":"bs-rates-d:%","capRates":"bs-day-rates","capGeo":"bs-day-geocode","capAreas":"bs-day-areas"}';
begin
  perform public.assert_admin();
  if me.role is distinct from 'owner' then perform public.bad('Only an owner can reset Security.'); end if;
  if not public.owner_unlocked('__security__') then perform public.bad('Turn on Owner mode first (owner password).'); end if;
  if p_name = 'all' then
    update public.throttle set at = 0 where at > 0 and k not like 'sudo:%' and k not like 'logclr:%';
  else
    pat := m ->> p_name;
    if pat is null then perform public.bad('Unknown limit.'); end if;
    update public.throttle set at = 0 where at > 0 and k like pat;
    if p_name like 'cap%' then update public.throttle set at = 0 where at > 0 and k like 'alert:' || p_name || ':%'; end if;
  end if;
  get diagnostics n = row_count;
  perform public.log_act('Security counters reset', case when p_name = 'all' then 'everything' else p_name end);
  return jsonb_build_object('ok', true, 'n', n);
end $$;

revoke all on function public.admin_security_get(), public.admin_security_alerts(), public.admin_security_seen(), public.admin_security_set(jsonb), public.admin_security_reset(text) from public, anon, authenticated;
grant execute on function public.admin_security_get(), public.admin_security_alerts(), public.admin_security_seen(), public.admin_security_set(jsonb), public.admin_security_reset(text) to authenticated;


-- ===== 20260131000000_sameday_late_night_courier.sql =====
-- Callebrownies migration 31: delivery days and the evening courier stop.
--  * Sameday after the order-by time: a customer who saw the "Sameday closed" pop-up and still chose Sameday
--    can order it (the order is marked "Same day (after cut-off)")
--  * Scheduled delivery is never today: tomorrow at the earliest, up to "schedMaxDays" days (Delivery & courier, default 7)
--  * an hourly job calls the courier webhook function: in the evening it stops the driver search for bookings made
--    before the stop time, and the next morning it searches again (both set in Delivery & courier)
-- Safe to run more than once. Run after migration 30.

do $$
declare
  r text[][] := array[
    ['if sh >= coalesce((s ->> ''samedayCutoff'')::int, 15) then',
     'if sh >= coalesce((s ->> ''samedayCutoff'')::int, 15) and coalesce(p ->> ''sdLate'', '''') <> ''true'' then'],
    ['dte := today; v_day := today::text; v_time := ''Same day'';',
     'dte := today; v_day := today::text; v_time := case when sh >= coalesce((s ->> ''samedayCutoff'')::int, 15) then ''Same day (after cut-off)'' else ''Same day'' end;'],
    ['if sh >= coalesce((s ->> ''cutoffHour'')::int, 20) then earliest := earliest + 1; end if;',
     'if sh >= coalesce((s ->> ''cutoffHour'')::int, 20) then earliest := earliest + 1; end if;
    if v_speed = ''scheduled'' and earliest <= today then earliest := today + 1; end if;'],
    ['if dte < earliest or dte > earliest + 6 then',
     'if dte < earliest or dte > earliest + (case when v_speed = ''scheduled'' then greatest(1, least(60, coalesce((s ->> ''schedMaxDays'')::int, 7))) else 7 end) - 1 then']];
  i int; d text; n text;
begin
  select pg_get_functiondef(p.oid) into d from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = 'place_order' limit 1;
  n := d;
  for i in 1 .. array_length(r, 1) loop
    if position(r[i][2] in n) = 0 then n := replace(n, r[i][1], r[i][2]); end if;
  end loop;
  if n <> d then execute n; end if;
end $$;

-- the hourly courier job (the webhook secret is read when it runs, it is not stored in the job)
create extension if not exists pg_net;
create extension if not exists pg_cron;
select cron.schedule('dd-courier-sweep', '0 * * * *', $job$
  select net.http_post(
    url := 'https://uvxocwqzjilabkywfroq.supabase.co/functions/v1/biteship-webhook?k=' || coalesce((select data ->> 'v' from public.private_kv where key = 'webhook_secret'), ''),
    body := '{"cron":"sweep"}'::jsonb,
    headers := '{"Content-Type":"application/json"}'::jsonb,
    timeout_milliseconds := 60000)
$job$);


-- ===== 20260201000000_brownie_bases.sql =====
-- Callebrownies migration 32: brownie base (step 1 in the shop, before the box).
--  * a new collection "bases" (name, description, extra price per brownie, on/off), edited in Boxes & extras
--    like box sizes; starts with Semisweet and Bittersweet
--  * while at least one base is switched on, every order must have one; it is saved on the order as
--    "batter" {id, name} and its price as "batterFee", which is part of the total
--  * same rules as box sizes: "Boxes & extras" access to change, owner password for a price, owner only to delete
-- Safe to run more than once. Run after migration 31.

-- the two starting bases (only when there are none yet)
insert into public.coll (coll, id, pos, data, updated_at)
select 'bases', b.id, b.pos, b.data, public.now_ms() from (values
  ('semisweet', 0, '{"id":"semisweet","name":"Semisweet","desc":"","price":0,"active":true}'::jsonb),
  ('bittersweet', 1, '{"id":"bittersweet","name":"Bittersweet","desc":"","price":0,"active":true}'::jsonb)) as b(id, pos, data)
where not exists (select 1 from public.coll where coll = 'bases');

do $do$
declare d text; n text;
begin
  -- the team can save the new collection
  d := pg_get_functiondef('public.admin_put_rows(text,jsonb)'::regprocedure);
  if position('''bases''' in d) = 0 then
    n := replace(d, $a$p_coll not in ('sizes',$a$, $a$p_coll not in ('bases','sizes',$a$);
    if n = d then raise exception 'admin_put_rows patch did not apply'; end if;
    execute n;
  end if;

  -- access, price and delete rules, activity log name
  d := pg_get_functiondef('public.coll_guard()'::regprocedure);
  if position('''bases''' in d) = 0 then
    n := replace(d, $a$when 'sizes' then 'boxes'$a$, $a$when 'sizes' then 'boxes' when 'bases' then 'boxes'$a$);
    n := replace(n, $a$c in ('products','categories','sizes','addons')$a$, $a$c in ('products','categories','sizes','addons','bases')$a$);
    n := replace(n, $a$c in ('sizes','addons') and$a$, $a$c in ('sizes','addons','bases') and$a$);
    n := replace(n, $a$when 'sizes' then 'box size'$a$, $a$when 'sizes' then 'box size' when 'bases' then 'brownie base'$a$);
    if (length(n) - length(replace(n, '''bases''', ''))) / length('''bases''') < 5 then raise exception 'coll_guard patch did not apply'; end if;
    execute n;
  end if;

  -- the shop gets the list
  d := pg_get_functiondef('public.shop_public()'::regprocedure);
  if position('''bases''' in d) = 0 then
    n := replace(d, $a$'sizes', public.coll_arr('sizes'),$a$, $a$'sizes', public.coll_arr('sizes'), 'bases', public.coll_arr('bases'),$a$);
    if n = d then raise exception 'shop_public patch did not apply'; end if;
    execute n;
  end if;

  -- placing or editing an order checks the base, adds its price and saves it
  d := pg_get_functiondef('public.place_order(jsonb)'::regprocedure);
  if position('batter_fee' in d) = 0 then
    n := replace(d, 'own_stock int;', 'own_stock int; v_batter jsonb; batter_fee numeric := 0; bt record;');
    n := replace(n, '  -- sale + coupon + delivery fee', $a$  -- brownie base: needed while at least one base is switched on; its price is per brownie
  if exists (select 1 from public.coll where coll = 'bases' and coalesce((data ->> 'active')::boolean, true)) then
    select * into bt from public.coll where coll = 'bases' and id = coalesce(p ->> 'batter', '') and coalesce((data ->> 'active')::boolean, true);
    if not found then perform public.bad('Please choose your brownie base.'); end if;
    batter_fee := round(greatest(0, coalesce((bt.data ->> 'price')::numeric, 0)) * v_size, 2);
    v_batter := jsonb_build_object('id', bt.id, 'name', coalesce(bt.data ->> 'name', ''));
  end if;

  -- sale + coupon + delivery fee$a$);
    n := replace(n, 'total := round(base - sd - cdisc + surcharge + addons_total + fee, 2);',
                    'total := round(base - sd - cdisc + surcharge + batter_fee + addons_total + fee, 2);');
    n := replace(n, $a$'addonsTotal', addons_total, 'fee', fee,$a$, $a$'batter', v_batter, 'batterFee', batter_fee, 'addonsTotal', addons_total, 'fee', fee,$a$);
    if position('Please choose your brownie base' in n) = 0 or position('+ batter_fee +' in n) = 0
       or (length(n) - length(replace(n, '''batterFee''', ''))) / length('''batterFee''') <> 2 then
      raise exception 'place_order patch did not apply'; end if;
    execute n;
  end if;
end $do$;

